.modal-footer-center{justify-content:center;gap:15px}
.modal-footer-between{justify-content:space-between;align-items:center}
.btn-md{padding:10px 20px!important;font-size:14px!important}
.btn-lg{padding:10px 25px!important;font-size:14px!important}
.si-purple{background:rgba(212,144,14,.15);color:#D4900E}
.si-green{background:rgba(46,213,115,.15);color:#2ed573}
.si-orange{background:rgba(255,159,67,.15);color:#ff9f43}
