.habit-item {
    background: rgba(255,255,255,0.025);
    border: 1px solid rgba(255,255,255,0.07);
    border-left: 3px solid var(--primary-color);
    padding: 14px 16px;
    border-radius: 10px;
    display: flex;
    align-items: flex-start;
    gap: 14px;
    transition: background 0.15s;
}
.habit-item:hover .habit-side-actions { opacity: 1; }

.habit-icon-wrapper {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    background: rgba(212,144,14,0.1);
    color: var(--primary-color);
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 14px;
    flex-shrink: 0;
}

.habit-details {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 9px;
}

.habit-header-top {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}
.habit-name {
    font-size: 14px;
    font-weight: 600;
    color: #fff;
    line-height: 1.3;
}
.habit-streak {
    font-size: 11px;
    font-weight: 500;
    color: var(--primary-color);
    display: inline-flex;
    align-items: center;
    gap: 4px;
    opacity: 0.8;
}
.habit-category-tag {
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 20px;
    background: rgba(255,255,255,0.06);
    color: var(--text-muted);
    border: 1px solid rgba(255,255,255,0.07);
    margin-left: auto;
}



/* Progress */
.habit-progress-wrapper { width: 100%; }
.habit-progress-container {
    width: 100%;
    height: 4px;
    background: rgba(255,255,255,0.07);
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 5px;
}
.habit-progress-fill {
    height: 100%;
    background: #2ed573;
    border-radius: 4px;
    transition: width 0.5s ease;
}
.habit-progress-text {
    font-size: 11px;
    color: var(--text-muted);
    display: block;
    text-align: right;
}

/* Tracker dots */
.habit-tracker {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    max-height: 120px;
    overflow-y: auto;
}
.habit-tracker::-webkit-scrollbar { width: 3px; }
.habit-tracker::-webkit-scrollbar-track { background: transparent; }
.habit-tracker::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 3px; }

.tracker-dot {
    width: 26px;
    height: 26px;
    border-radius: 6px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.09);
    transition: background 0.15s, border-color 0.15s;
    cursor: pointer;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 10px;
    font-weight: 600;
    color: var(--text-muted);
    flex-shrink: 0;
}
.tracker-dot.locked { cursor: default; opacity: 0.6; }
.tracker-dot:not(.locked):hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.15); }
.tracker-dot.today {
    border-color: var(--primary-color);
    color: var(--primary-color);
    background: rgba(212,144,14,0.1);
}
.tracker-dot.missed {
    background: rgba(255,71,87,0.08);
    border-color: rgba(255,71,87,0.25);
    color: rgba(255,71,87,0.6);
}

/* Sağ aksiyon kolonu */
.habit-actions {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 8px;
    flex-shrink: 0;
}
.complete-today-btn {
    background: rgba(46,213,115,0.1);
    color: #2ed573;
    border: 1px solid rgba(46,213,115,0.22);
    padding: 7px 14px;
    border-radius: 20px;
    cursor: pointer;
    font-weight: 600;
    font-size: 12px;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    white-space: nowrap;
    font-family: inherit;
}
.complete-today-btn.done:hover { background: rgba(46,213,115,0.28); }

.habit-side-actions {
    display: flex;
    gap: 4px;
    opacity: 0;
    transition: opacity 0.15s;
}
.edit-habit-btn,
.habit-del-btn {
    background: none;
    border: 1px solid transparent;
    border-radius: 6px;
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 11px;
    transition: background 0.15s, border-color 0.15s, color 0.15s;
    font-family: inherit;
}
.edit-habit-btn:hover { background: rgba(255,255,255,0.07); border-color: rgba(255,255,255,0.12); color: #fff; }
.habit-del-btn { color: rgba(255,71,87,0.35); }
.habit-del-btn:hover { background: rgba(255,71,87,0.08); border-color: rgba(255,71,87,0.2); color: #ff4757; }

/* ── Alışkanlık Oluşturma Modali ── */
.habit-modal-content {
    max-width: 500px !important;
    border-radius: 14px !important;
}
#habit-create-modal .modal-header {
    padding: 16px 22px 14px !important;
    border-bottom: 1px solid var(--b1, rgba(255,255,255,0.06)) !important;
}
#habit-create-modal .modal-header h2 { font-size: 16px; font-weight: 700; }
#habit-create-modal .modal-body {
    padding: 20px 22px !important;
    display: flex;
    flex-direction: column;
    gap: 14px;
}
#habit-create-modal .modal-footer {
    padding: 14px 22px 18px !important;
    border-top: 1px solid var(--b1, rgba(255,255,255,0.06)) !important;
    justify-content: flex-end;
    gap: 8px;
}

.hm-field { display: flex; flex-direction: column; gap: 6px; }
.hm-field-half { flex: 1; }
.hm-label {
    font-size: 11px;
    font-weight: 600;
    color: var(--t2, #888);
    text-transform: uppercase;
    letter-spacing: 0.4px;
    display: flex;
    align-items: center;
    gap: 5px;
}
.hm-label i { color: var(--a, #D4900E); opacity: 0.75; font-size: 10.5px; }
.hm-optional { font-weight: 400; text-transform: none; letter-spacing: 0; font-size: 10.5px; color: var(--t2, #888); }
.hm-sync-hint { color: #ff6b6b; font-size: 11px; }



@keyframes hm-emoji-pop {
    from { opacity:0; transform:translateY(-4px) scale(.97); }
    to   { opacity:1; transform:translateY(0) scale(1); }
}
.hm-emoji-picker.hidden { display:none; }



.hm-row { display: flex; gap: 12px; }

.hm-stepper {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    background: rgba(255,255,255,0.03);
    border: 1px solid var(--b2, rgba(255,255,255,0.11));
    border-radius: 12px;
    padding: 9px 12px;
    box-sizing: border-box;
}
.hm-step-btn {
    background: transparent;
    border: none;
    border-radius: 8px;
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: rgba(255,255,255,0.6);
    font-size: 11px;
    transition: background 0.15s, border-color 0.15s, color 0.15s;
    flex-shrink: 0;
}
.hm-step-btn:hover { background: rgba(212,144,14,0.16); border-color: rgba(212,144,14,0.35); color: #fff; }
.hm-step-input {
    width: 48px;
    text-align: center;
    background: transparent;
    background-color: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
    color: #fff;
    font-size: 16px;
    font-weight: 700;
    outline: none;
    font-family: inherit;
    -webkit-appearance: none;
    -moz-appearance: textfield;
    appearance: none;
}
/* #habit-target artık type="text" (native number-spinner farklılıklarını
   önlemek için) — bu da onu genel ".modal-content input[type='text']"
   kuralının (arkaplan/kenarlık/border-radius, !important) kapsamına
   sokuyordu ve rakamın etrafında istenmeyen bir "hap" görünümü oluşuyordu.
   Buradaki yüksek özgüllük (id + iki class) o kuralı geçersiz kılar. */
#habit-create-modal .modal-content .hm-stepper .hm-step-input {
    background: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}
.hm-step-label { font-size: 12px; color: var(--t2, #888); }

.hm-select {
    width: 100%;
    padding: 9px 12px !important;
    font-size: 13px !important;
}
.hm-date {
    width: 100%;
    padding: 9px 12px !important;
    font-size: 13px !important;
    color: #fff !important;
}
.hm-cat-row { display: flex; gap: 6px; align-items: center; }
.hm-cat-row .hm-select { flex: 1; }
.hm-cat-btn {
    width: 34px !important;
    height: 34px !important;
    border-radius: 7px !important;
    flex-shrink: 0;
    color: var(--t2, #888) !important;
    border: 1px solid var(--b2, rgba(255,255,255,0.11)) !important;
    background: rgba(255,255,255,0.03) !important;
}
.hm-cat-btn:hover { color: #fff !important; background: rgba(212,144,14,0.1) !important; border-color: rgba(212,144,14,0.3) !important; }
.hm-cat-del:hover { color: #ff4757 !important; background: rgba(255,71,87,0.08) !important; border-color: rgba(255,71,87,0.2) !important; }

.hm-pills { margin-top: 2px; }

.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    opacity: 1;
    visibility: visible;
    transition: 0.3s ease;
}

.modal-overlay.hidden {
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
}

.modal-content {
    width: 90%;
    max-width: 400px;
    padding: 30px;
    transform: translateY(0) scale(1);
    opacity: 1;
    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.25s ease;
}

.modal-overlay.hidden .modal-content {
    transform: translateY(18px) scale(0.96);
    opacity: 0;
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

.modal-header h2 {
    font-size: 20px;
    font-weight: 600;
    color: #fff;
}

.modal-body p {
    color: var(--text-muted);
    font-size: 14px;
    margin-bottom: 15px;
}

.premium-input {
    width: 100%;
    background: rgba(0, 0, 0, 0.2);
    border: 1px solid var(--glass-border);
    color: #fff;
    padding: 12px 15px;
    border-radius: 12px;
    font-size: 15px;
    outline: none;
    transition: 0.3s;
}

.premium-input:focus {
    border-color: var(--primary-color);
    box-shadow: 0 0 10px rgba(212, 144, 14, 0.3);
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 25px;
}

.modal-icon-wrapper {
    width: 70px;
    height: 70px;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    margin: 0 auto 20px auto;
    font-size: 32px;
    transition: 0.3s;
}

.modal-icon-wrapper.warning{background:rgba(255,71,87,.15);color:#ff4757;box-shadow:0 0 20px rgba(255,71,87,.2)}
.modal-icon-wrapper.success{background:rgba(46,213,115,.15);color:#2ed573;box-shadow:0 0 20px rgba(46,213,115,.2)}
.modal-icon-wrapper.info{background:rgba(212,144,14,.15);color:var(--primary-color);box-shadow:0 0 20px rgba(212,144,14,.2)}

.timer-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 16px 40px;
    margin-top: 10px;
    transition: all 0.5s ease;
}

.focus-quote {
    font-style: italic;
    color: var(--text-muted);
    margin-bottom: 14px;
    font-size: 13px;
    text-align: center;
    min-height: 32px;
    transition: all 0.5s ease;
}

.active-focus-task {
    background: rgba(212, 144, 14, 0.15);
    border: 1px solid var(--primary-color);
    padding: 10px 18px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
    width: 100%;
    max-width: 450px;
    box-shadow: 0 4px 15px rgba(212, 144, 14, 0.2);
    transition: all 0.5s ease;
}

.active-focus-task.hidden {
    display: none;
}

.active-focus-task i.fa-crosshairs {
    color: var(--primary-color);
    font-size: 20px;
    animation: pulse 2s infinite;
}

@keyframes pulse {
    0% { transform: scale(1); }
    50% { transform: scale(1.2); }
    100% { transform: scale(1); }
}

.focus-label {
    color: var(--text-muted);
    font-size: 14px;
}

#focus-task-name {
    color: #fff;
    font-weight: 600;
    font-size: 16px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 200px;
}

.clear-focus-btn {
    background: transparent;
    border: none;
    color: #ff4757;
    font-size: 18px;
    cursor: pointer;
    margin-left: auto;
    opacity: 0.6;
    transition: 0.3s;
}

.clear-focus-btn:hover {
    opacity: 1;
    transform: scale(1.1);
}

.timer-modes {
    display: flex;
    gap: 10px;
    margin-bottom: 16px;
    background: rgba(0, 0, 0, 0.2);
    padding: 6px;
    border-radius: 14px;
    transition: all 0.5s ease;
}

.mode-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    padding: 10px 20px;
    border-radius: 12px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: 0.3s;
}

.mode-btn:hover { color: #fff; }
.mode-btn.active {
    background: var(--primary-color);
    color: #fff;
    box-shadow: 0 4px 15px rgba(212, 144, 14, 0.4);
}

.timer-display-wrapper {
    position: relative;
    margin-bottom: 14px;
}

.timer-circle {
    width: 280px;
    height: 280px;
    border-radius: 50%;
    background: transparent !important;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 64px; /* 3 haneli rakamların sığması için 64px yapıldı */
    font-weight: 700;
    font-variant-numeric: tabular-nums;
    box-shadow: none !important;
    border: none !important;
    transition: all 0.5s ease;
    position: relative;
}

.timer-ring-progress {
    filter: drop-shadow(0 0 4px rgba(212, 144, 14, 0.4));
}

.timer-circle.running {
    box-shadow: none !important;
    background: transparent !important;
    border: none !important;
}

.timer-circle.running .timer-ring-progress {
    /* Tüm parlama/gölge efektleri tamamen kapatıldı */
    filter: none !important;
}

.timer-text {
    display: grid;
    grid-template-columns: 1fr 20px 1fr;
    align-items: center;
    width: 100%;
}

#minutes,
#gf-minutes {
    text-align: right;
}

#seconds,
#gf-seconds {
    text-align: left;
}

.timer-circle .colon {
    margin: 0;
    text-align: center;
    animation: blink 1s infinite;
}

.timer-circle.paused .colon {
    animation: none;
    opacity: 1;
}

@keyframes blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
}

.timer-controls {
    display: flex;
    gap: 20px;
    transition: all 0.5s ease;
}

.control-btn {
    border: none;
    padding: 15px 30px;
    border-radius: 12px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 10px;
    transition: 0.3s;
}

.control-btn.primary {
    background: #2ed573;
    color: #fff;
    box-shadow: 0 4px 15px rgba(46, 213, 115, 0.4);
}
.control-btn.primary:hover { background: #26b360; transform: translateY(-2px); }

.control-btn.secondary {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}
.control-btn.secondary:hover { background: rgba(255, 255, 255, 0.2); }

.control-btn.hidden {
    display: none;
}

.control-btn#pause-btn {
    background: #ffa502;
    color: #fff;
    box-shadow: 0 4px 15px rgba(255, 165, 2, 0.4);
}
.control-btn#pause-btn:hover { background: #df9000; transform: translateY(-2px); }

.ambient-panel {
    margin-top: 35px;
    background: rgba(0, 0, 0, 0.2);
    border-radius: 16px;
    padding: 20px 30px;
    width: 100%;
    max-width: 450px;
    display: flex;
    flex-direction: column;
    gap: 15px;
    border: 1px solid var(--glass-border);
    transition: all 0.5s ease;
}



.ambient-title {
    display: flex;
    align-items: center;
    gap: 8px;
}



/* Başlıktaki ikon butonları (mikser / küçült) */




.ambient-mixer-count {
    position: absolute;
    top: -5px;
    right: -5px;
    min-width: 16px;
    height: 16px;
    padding: 0 3px;
    border-radius: 8px;
    background: var(--primary-color);
    color: #fff;
    font-size: 10px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
}

.ambient-mixer-count.hidden {
    display: none;
}

/* ── Kart çevirme (flip) animasyonu ── */


.ambient-flip-inner {
    transition: transform 0.6s ease;
    transform-style: preserve-3d;
}

.ambient-flip-inner.ambient-spin {
    transform: rotateY(360deg);
}

.ambient-flip-front,
.ambient-flip-back {
    display: none;
    flex-direction: column;
    gap: 15px;
}

.ambient-flip-front.ambient-face-visible,
.ambient-flip-back.ambient-face-visible {
    display: flex;
}

/* ── Ön yüz: minimal hızlı ses seçimi ── */


.quick-sound-btn {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    color: var(--text-muted);
    font-size: 19px;
    cursor: pointer;
    transition: all 0.25s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.quick-sound-btn:hover {
    background: rgba(255,255,255,0.12);
    color: #fff;
    transform: translateY(-2px);
}

.quick-sound-btn.active {
    background: var(--primary-color);
    border-color: var(--primary-color);
    color: #fff;
    box-shadow: 0 0 18px rgba(212,144,14,0.55);
}

/* ── Ön yüz: ana ses seviyesi / sessize alma ── */
.ambient-master-volume {
    display: flex;
    align-items: center;
    gap: 12px;
}

.ambient-master-volume .premium-range {
    flex: 1;
}

.ambient-master-volume .ambient-mixer-pct {
    min-width: 38px;
}

/* ── Ses kartları (grid) ── */


.sound-card {
    position: relative;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    border-radius: 14px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 600;
    text-align: left;
    cursor: pointer;
    transition: all 0.25s ease;
}

.sound-card:hover {
    background: rgba(255,255,255,0.08);
    color: #fff;
    transform: translateY(-2px);
}

.sound-card.active {
    background: linear-gradient(135deg, rgba(212,144,14,0.25), rgba(212,144,14,0.08));
    border-color: var(--primary-color);
    color: #fff;
    box-shadow: 0 4px 18px rgba(212,144,14,0.25);
}



.sound-card.active .sound-card-icon {
    background: var(--primary-color);
    color: #fff;
}



.sound-card.active .sound-card-pulse {
    opacity: 1;
    animation: ambientPulse 1.4s ease-in-out infinite;
}

@keyframes ambientPulse {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.6); opacity: 0.4; }
}

/* ── Ön yüz alt satırı ── */


#ambient-stop-all {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 20px;
    background: rgba(255,71,87,0.08);
    border: 1px solid rgba(255,71,87,0.25);
    color: #ff6b81;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

#ambient-stop-all:hover {
    background: rgba(255,71,87,0.18);
}

.ambient-mixer-empty {
    text-align: center;
    font-size: 13px;
    color: var(--text-muted);
    padding: 18px 10px;
    border: 1px dashed rgba(255,255,255,0.1);
    border-radius: 12px;
}

/* ── ODAK SESLERİ MİKSER SATIRLARI ── */
.ambient-mixer-rows {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.ambient-mixer-row {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--text-muted);
    font-size: 13px;
    animation: ambientRowIn 0.25s ease;
}

.ambient-mixer-row i {
    width: 16px;
    text-align: center;
    color: var(--primary-color);
}

.ambient-mixer-row .premium-range {
    flex: 1;
}

.ambient-mixer-pct {
    min-width: 36px;
    text-align: right;
