/* ═══ TIMER SCENE ═══ */
.timer-scene-section {
    position: relative;
    overflow: hidden;
    min-height: calc(100vh - 56px);
    display: flex;
    flex-direction: column;
    align-items: stretch;
}
#zamanlayici .timer-container {
    align-self: center;
}
.timer-scene-video {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
    z-index: 0;
    opacity: 0;
    transition: opacity 1.2s ease;
    pointer-events: none;
}
.timer-scene-video.active {
    opacity: 1;
}
.timer-scene-dim {
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, rgba(10,10,20,0.55) 0%, rgba(10,10,20,0.35) 50%, rgba(10,10,20,0.7) 100%);
    z-index: 1;
    opacity: 0;
    transition: opacity 1.2s ease;
    pointer-events: none;
}
.timer-scene-video.active ~ .timer-scene-dim,
.timer-scene-section.has-scene .timer-scene-dim {
    opacity: 1;
}
#zamanlayici .section-header,
#zamanlayici .timer-container {
    position: relative;
    z-index: 2;
}
#zamanlayici.has-scene .timer-section-header h1,
#zamanlayici.has-scene .timer-section-header p {
    text-shadow: 0 1px 8px rgba(0,0,0,0.5);
}

