/* ============ PREMIUM AMBIENT VISUALS ============ */

@keyframes premiumRainFall {
    0%   { transform: translateY(0) rotate(14deg); opacity: 0; }
    8%   { opacity: 1; }
    92%  { opacity: 0.7; }
    100% { transform: translateY(110vh) rotate(14deg); opacity: 0; }
}

@keyframes rainRippleOut {
    0%   { transform: scale(0); opacity: 0.8; }
    100% { transform: scale(1);  opacity: 0; }
}

@keyframes lightningPop {
    0%   { opacity: 0; }
    25%  { opacity: 1; }
    50%  { opacity: 0.2; }
    75%  { opacity: 0.8; }
    100% { opacity: 0; }
}






@keyframes waveScroll1 { from { transform: translateX(0); } to { transform: translateX(-50%); } }
@keyframes waveScroll2 { from { transform: translateX(-5%); } to { transform: translateX(-55%); } }
@keyframes waveScroll3 { from { transform: translateX(-10%); } to { transform: translateX(-60%); } }
/* ── Decline Toast Animasyonu ── */
@keyframes slideInRight {
    from { opacity: 0; transform: translateX(60px) scale(0.95); }
    to   { opacity: 1; transform: translateX(0) scale(1); }
}
@keyframes slideOutRight {
    from { opacity: 1; transform: translateX(0) scale(1); }
    to   { opacity: 0; transform: translateX(60px) scale(0.95); }
}

@keyframes foamFloat {
    0%   { transform: translateY(0) scale(1); opacity: 0.5; }
    60%  { opacity: 0.2; }
    100% { transform: translateY(-70px) scale(0.2); opacity: 0; }
}

@keyframes fireflyDrift {
    0%   { transform: translate(0,0) scale(0.6); opacity: 0; }
    20%  { opacity: 1; }
    50%  { transform: translate(var(--fx), var(--fy)) scale(1.4); opacity: 0.8; }
    80%  { opacity: 0.3; }
    100% { transform: translate(calc(var(--fx)*0.7), calc(var(--fy)*1.3)) scale(0.5); opacity: 0; }
}

@keyframes leafTumble {
    0%   { transform: translateY(-20px) rotate(0deg) translateX(0); opacity: 0.9; }
    33%  { transform: translateY(30vh) rotate(120deg) translateX(var(--lx)); opacity: 0.7; }
    66%  { transform: translateY(60vh) rotate(240deg) translateX(calc(var(--lx)*-0.5)); opacity: 0.5; }
    100% { transform: translateY(105vh) rotate(360deg) translateX(var(--lx)); opacity: 0; }
}

@keyframes mistPulse {
    from { opacity: 0.2; transform: scale(1) translateX(0); }
    to   { opacity: 0.5; transform: scale(1.15) translateX(20px); }
}

@keyframes glowBreath {
    from { opacity: 0.6; transform: scaleX(0.96); }
    to   { opacity: 1;   transform: scaleX(1.04); }
}

@keyframes fireAscend {
    0%   { transform: translateY(0) scaleX(1) rotate(var(--fr));  opacity: 0.95; }
    35%  { transform: translateY(calc(var(--fh)*0.35)) scaleX(0.85) rotate(calc(var(--fr) + 8deg)); opacity: 0.75; }
    70%  { transform: translateY(calc(var(--fh)*0.70)) scaleX(0.5)  rotate(calc(var(--fr) - 6deg)); opacity: 0.35; }
    100% { transform: translateY(var(--fh)) scaleX(0.1) rotate(var(--fr)); opacity: 0; }
}

@keyframes emberAscend {
    0%   { transform: translate(0,0) scale(1); opacity: 1; }
    100% { transform: translate(var(--ex), var(--ey)) scale(0); opacity: 0; }
}

.calendar-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    height: 100%;
}

.calendar-left {
    padding: 16px;
    display: flex;
    flex-direction: column;
    min-width: 0;
    overflow: hidden;
}

.calendar-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 14px;
}

.calendar-header h2 {
    font-size: 20px;
    font-weight: 600;
}

.cal-nav-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-size: 18px;
    cursor: pointer;
    transition: 0.3s;
    padding: 5px;
}

.cal-nav-btn:hover {
    color: var(--primary-color);
}

.calendar-weekdays {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    text-align: center;
    font-weight: 500;
    color: var(--text-muted);
    font-size: 14px;
    margin-bottom: 15px;
}

.calendar-days {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 8px;
}

.cal-day {
    aspect-ratio: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    border-radius: 12px;
    cursor: pointer;
    font-size: 15px;
    font-weight: 500;
    transition: 0.2s;
    background: rgba(255,255,255,0.02);
    border: 1px solid transparent;
    position: relative;
    overflow: hidden;
    min-width: 0;
}

.cal-day:hover:not(.empty) {
    background: rgba(255,255,255,0.1);
}

/* Heat overlay: görev yoğunluğuna göre artan arka plan tonu */
.cal-day[data-heat="1"] { background: rgba(212,144,14,0.07); }
.cal-day[data-heat="2"] { background: rgba(212,144,14,0.13); }
.cal-day[data-heat="3"] { background: rgba(212,144,14,0.21); }
.cal-day[data-heat="4"] { background: rgba(212,144,14,0.30); border-color: rgba(212,144,14,0.25); }

/* Hover'da heat tonu biraz daha belirgin olsun */
.cal-day[data-heat]:hover:not(.empty) { filter: brightness(1.12); }

/* Seçili ve today state'leri heat'i ezmemeli */
.cal-day.selected[data-heat] { background: var(--primary-color); filter: none; }
.cal-day.today[data-heat]:not(.selected) { background: rgba(212,144,14,0.21); }

.cal-day.empty {
    background: transparent;
    cursor: default;
}

.cal-day.today {
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.cal-day.selected {
    background: var(--primary-color);
    color: #fff;
    box-shadow: 0 4px 10px rgba(212, 144, 14, 0.4);
}

.cal-day.has-event::after {
    content: '';
    width: 6px;
    height: 6px;
    background-color: #ff9f43;
    border-radius: 50%;
    position: absolute;
    bottom: 8px;
}

.cal-day.selected.has-event::after {
    background-color: #fff;
}































