/* --- ZAMANLAYICI İLERLEME ÇEMBERİ (PROGRESS RING) --- */
.timer-svg {
    position: absolute;
    top: 0;
    left: 0;
    transform: rotate(-90deg);
    width: 100%;
    height: 100%;
    pointer-events: none;
}

.timer-ring-bg {
    fill: transparent;
    stroke: transparent; /* Altından sırıtan ince gri halkayı görünmez yaptık */
    stroke-width: 8;
}

.timer-ring-progress {
    fill: transparent;
    stroke: var(--primary-color);
    stroke-width: 8;
    stroke-linecap: round;
    stroke-dasharray: 816.8; /* 2 * pi * r (130) */
    stroke-dashoffset: 0;
    transition: stroke-dashoffset 1s linear, stroke 0.3s ease;
}

/* Süre çalışırken parlaması için ufak bir gölge */
.timer-circle.running .timer-ring-progress {
    filter: drop-shadow(0 0 8px var(--primary-color));
}

/* --- MOLA İÇİN NEFES ALMA (BREATHING) EFEKTİ --- */
@keyframes breathingEffect {
    0% { transform: scale(1); box-shadow: none !important; }
    50% { transform: scale(1.05); box-shadow: none !important; }
    100% { transform: scale(1); box-shadow: none !important; }
}

.timer-circle.breathing-active {
    animation: breathingEffect 8s ease-in-out infinite;
    border: none !important;
    background: transparent !important;
    box-shadow: none !important;
}

.timer-circle.breathing-active .timer-ring-progress {
    stroke: #2ed573 !important;
    filter: none !important; /* Gölge tamamen kaldırıldı */
}

/* Ayarlardaki basit tarayıcı oklarını gizleyen Premium kod */
input[type="number"].setting-input::-webkit-inner-spin-button,
input[type="number"].setting-input::-webkit-outer-spin-button {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
}
input[type="number"].setting-input {
    -moz-appearance: textfield;
    text-align: center;
    font-weight: 600;
    font-size: 16px;
}

/* ============ SADECE ODAK MODUNDA TAM ŞEFFAFLIK ============ */
body.focus-mode-active .app-container,
body.focus-mode-active .timer-container {
    background: transparent !important;
    border: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
}

body.focus-mode-active .background-blobs {
    display: none !important;
}

/* ============ AKILLI YÜZEN PANEL (TELEPORT EFEKTİ) ============ */
.ambient-panel.floating-ambient {
