/* ═══════════════════════════════════════════
   PREMIUM ONBOARDING TOUR — v2
═══════════════════════════════════════════ */

.tour-overlay {
    background: rgba(0, 0, 0, 0.65) !important;
    backdrop-filter: blur(4px) !important;
    pointer-events: auto !important;
}
.tour-overlay.active { opacity: 1; visibility: visible; }

/* ── TOOLTIP KAPSAYICI ── */
.tour-tooltip {
    position: fixed;
    z-index: 10010;
    width: 340px;
    background: linear-gradient(160deg, #1a1740 0%, #13102e 100%);
    border: 1px solid rgba(212,144,14,0.45);
    border-radius: 20px;
    box-shadow: 0 24px 60px rgba(0,0,0,0.7), 0 0 0 1px rgba(212,144,14,0.15), inset 0 1px 0 rgba(255,255,255,0.07);
    opacity: 0;
    visibility: hidden;
    transform: translateY(14px) scale(0.97);
    transition: opacity 0.35s cubic-bezier(0.34,1.56,0.64,1),
                transform 0.35s cubic-bezier(0.34,1.56,0.64,1),
                visibility 0.35s;
    pointer-events: auto;
    overflow: visible;
}
.tour-tooltip.active {
    opacity: 1;
    visibility: visible;
    transform: translateY(0) scale(1);
}

/* ── OK İŞARETİ ── */
.tour-tooltip-arrow {
    position: absolute;
    width: 14px;
    height: 14px;
    background: #1a1740;
    border: 1px solid rgba(212,144,14,0.45);
    transform: rotate(45deg);
    z-index: -1;
    transition: top 0.3s, left 0.3s, bottom 0.3s;
}
.tour-tooltip-arrow.arrow-top    { top: -8px; border-bottom: none; border-right: none; }
.tour-tooltip-arrow.arrow-bottom { bottom: -8px; border-top: none; border-left: none; }
.tour-tooltip-arrow.arrow-left   { left: -8px; top: 50%; margin-top:-7px; border-top: none; border-right: none; }
.tour-tooltip-arrow.arrow-right  { right: -8px; top: 50%; margin-top:-7px; border-bottom: none; border-left: none; }

/* ── HEADER ── */
.tour-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px 8px;
}
.tour-header-left {
    display: flex;
    align-items: center;
    gap: 8px;
}
.tour-badge {
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: #fff;
    background: linear-gradient(135deg, #D4900E, #D4900E);
    padding: 3px 10px;
    border-radius: 20px;
}
.tour-step-counter {
    font-size: 11px;
    font-weight: 600;
    color: rgba(255,255,255,0.35);
}
.tour-close-btn {
    width: 28px; height: 28px;
    border-radius: 50%;
    border: 1px solid rgba(255,255,255,0.1);
    background: rgba(255,255,255,0.06);
    color: rgba(255,255,255,0.4);
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    font-size: 13px;
    transition: background 0.2s, color 0.2s, transform 0.2s;
}
.tour-close-btn:hover {
    background: rgba(255,71,87,0.2);
    color: #ff4757;
    transform: rotate(90deg);
}

/* ── İLERLEME ÇUBUĞU ── */
.tour-progress-bar-wrap {
    height: 3px;
    background: rgba(255,255,255,0.07);
    margin: 0 16px;
    border-radius: 3px;
    overflow: hidden;
}
.tour-progress-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #D4900E, #D4900E);
    border-radius: 3px;
    transition: width 0.5s cubic-bezier(0.65,0,0.35,1);
    width: 0%;
}

/* ── GÖVDE ── */
.tour-body {
    padding: 18px 20px 8px;
    text-align: center;
}
.tour-icon-wrap {
    width: 56px; height: 56px;
    margin: 0 auto 12px;
    background: rgba(212,144,14,0.15);
    border: 1px solid rgba(212,144,14,0.25);
    border-radius: 16px;
    display: flex; align-items: center; justify-content: center;
    font-size: 26px;
    animation: tourIconPop 0.4s cubic-bezier(0.34,1.56,0.64,1);
}
@keyframes tourIconPop {
    from { transform: scale(0.5) rotate(-10deg); opacity: 0; }
    to   { transform: scale(1) rotate(0deg); opacity: 1; }
}
.tour-tooltip h3 {
    font-size: 15px;
    font-weight: 700;
    margin-bottom: 8px;
    color: #fff;
    line-height: 1.3;
}
.tour-tooltip p {
    font-size: 13px;
    line-height: 1.65;
    color: rgba(255,255,255,0.6);
    margin: 0;
}

/* ── FOOTER ── */
.tour-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px 16px;
    border-top: 1px solid rgba(255,255,255,0.05);
    margin-top: 14px;
}

/* Nokta göstergeler */
.tour-step-dots { display: flex; gap: 5px; align-items: center; }
.tour-dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: rgba(255,255,255,0.15);
    transition: all 0.35s cubic-bezier(0.34,1.56,0.64,1);
    cursor: pointer;
}
.tour-dot.active {
    width: 18px;
    border-radius: 3px;
    background: linear-gradient(90deg, #D4900E, #D4900E);
}

/* Geri butonu */
.tour-btn-ghost {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.12);
    color: rgba(255,255,255,0.5);
    padding: 7px 13px;
    border-radius: 10px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
    font-family: 'Inter', sans-serif;
    display: flex; align-items: center; gap: 6px;
    transition: all 0.2s;
}
.tour-btn-ghost:hover {
    border-color: rgba(212,144,14,0.5);
    color: #D4900E;
    background: rgba(212,144,14,0.08);
}

/* İleri / Bitir butonu */
.tour-btn-next {
    background: linear-gradient(135deg, #D4900E, #5a4bcf);
    border: none;
    color: #fff;
    padding: 8px 18px;
    border-radius: 10px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 700;
    font-family: 'Inter', sans-serif;
    display: flex; align-items: center; gap: 6px;
    box-shadow: 0 4px 16px rgba(212,144,14,0.4);
    transition: all 0.25s;
}
.tour-btn-next:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(212,144,14,0.55);
}
.tour-btn-next.finish {
    background: linear-gradient(135deg, #00b894, #00cec9);
    box-shadow: 0 4px 16px rgba(0,184,148,0.4);
}
.tour-btn-next.finish:hover { box-shadow: 0 8px 24px rgba(0,184,148,0.55); }

/* ── VURGULANAN ELEMENT ── */
@keyframes tourPulseGlow {
    0%   { box-shadow: 0 0 0 0 rgba(212,144,14,0.8), 0 0 0 4px rgba(212,144,14,0.3); }
    70%  { box-shadow: 0 0 0 12px rgba(212,144,14,0), 0 0 0 4px rgba(212,144,14,0.3); }
    100% { box-shadow: 0 0 0 0 rgba(212,144,14,0), 0 0 0 4px rgba(212,144,14,0.3); }
}
.tour-highlight-active {
    position: relative !important;
    z-index: 10005 !important;
    outline: 2px solid rgba(212,144,14,0.8) !important;
    outline-offset: 5px !important;
    border-radius: 10px !important;
    animation: tourPulseGlow 2s infinite !important;
}

/* ── TUR TAMAMLANDI (Konfeti arka planı için) ── */
@keyframes tourConfettiFall {
    0%   { transform: translateY(-10px) rotate(0deg); opacity: 1; }
