    text-align: center;
    letter-spacing: 0.3px;
}

/* ================================================================
   DRAG-AND-DROP PREVIEW (hücre içi bırakma önizlemesi)
   ================================================================ */
.cal-drop-preview {
    position: absolute;
    left: 2px; right: 2px;
    z-index: 8;
    border-radius: 6px;
    border: 2px dashed;
    font-size: 10px;
    font-weight: 700;
    color: rgba(255,255,255,0.9);
    padding: 3px 8px;
    pointer-events: none;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    transition: top 0.08s, height 0.08s;
    backdrop-filter: blur(4px);
}

/* ================================================================
   INLINE QUICK ADD POPUP
   ================================================================ */
#cal-iqa {
    position: absolute;
    z-index: 99999;
    width: 370px;
    background: rgba(20, 20, 26, 0.97);
    border: 1px solid rgba(212, 144, 14, 0.35);
    border-radius: 16px;
    padding: 14px 16px 14px;
    display: none;
    flex-direction: column;
    gap: 10px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.04);
    backdrop-filter: blur(20px);
}
.iqa-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
}
.iqa-time-badge {
    font-size: 11px;
    font-weight: 700;
    color: #D4900E;
    background: rgba(212,144,14,0.12);
    padding: 3px 10px;
    border-radius: 20px;
    border: 1px solid rgba(212,144,14,0.25);
    letter-spacing: 0.3px;
}
.iqa-close {
    background: none;
    border: none;
    color: rgba(255,255,255,0.35);
    font-size: 18px;
    cursor: pointer;
    line-height: 1;
    padding: 0 4px;
    transition: color 0.15s;
}
.iqa-close:hover { color: #fff; }
.iqa-input {
    width: 100%;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 10px;
    padding: 9px 13px;
    color: #fff;
    font-size: 14px;
    font-weight: 500;
    outline: none;
    box-sizing: border-box;
    transition: border-color 0.2s, box-shadow 0.2s;
}
.iqa-input:focus {
    border-color: rgba(212,144,14,0.5);
    box-shadow: 0 0 0 3px rgba(212,144,14,0.1);
}
.iqa-input::placeholder { color: rgba(255,255,255,0.3); }
.iqa-row {
    display: flex;
    gap: 8px;
    align-items: center;
}
.iqa-time-range {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    background: #2c2c33;
    border: 1px solid #444450;
    border-radius: 8px;
    padding: 8px 10px;
    box-sizing: border-box;
}
/* #cal-iqa ile kapsanmış — genel `input[type="time"]` kuralından (daha yüksek
   özgüllük: type+attribute selector) kazanabilmek için ID ile scope'landı. */
#cal-iqa .iqa-time-inp,
#cal-iqa input.iqa-time-inp[type="time"] {
    -webkit-appearance: none;
    appearance: none;
    background: #3a3a42 !important;
    border: 1px solid #5a5a64 !important;
    border-radius: 6px;
