}
.iqa-save-btn:hover { opacity: 0.88; transform: translateY(-1px); }
.iqa-save-btn:active { transform: translateY(0); }

/* ================================================================
   TAKVİM TAM EKRAN MODU
   ================================================================ */

/* Toolbar ayırıcı */


/* Büyütme butonu */
.cal-fs-btn {
    width: 36px !important;
    padding: 8px !important;
    justify-content: center;
    flex-shrink: 0;
    color: var(--text-muted) !important;
    transition: all 0.2s !important;
}
.cal-fs-btn:hover {
    color: #fff !important;
    background: rgba(212,144,14,0.2) !important;
}
.cal-fs-btn.fs-active {
    color: #D4900E !important;
    background: rgba(212,144,14,0.25) !important;
}

/* Tam ekran overlay */
#takvim.cal-is-fullscreen {
    position: fixed !important;
    inset: 0 !important;
    z-index: 9990 !important;
    border-radius: 0 !important;
    background: rgba(10, 8, 30, 0.98) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    overflow-y: auto !important;
    padding: 24px 32px !important;
    display: block !important;
}

/* Fullscreen'de toolbar sticky kalsın */
#takvim.cal-is-fullscreen .premium-cal-toolbar {
    position: sticky !important;
    top: 0 !important;
    z-index: 100 !important;
    background: rgba(10, 8, 30, 0.95) !important;
    backdrop-filter: blur(16px) !important;
    border-radius: 14px !important;
    margin-bottom: 16px !important;
}

/* Haftalık grid fullscreen'de daha uzun */
#takvim.cal-is-fullscreen .weekly-grid-inner {
    max-height: calc(100vh - 160px) !important;
}

/* Günlük grid fullscreen'de daha uzun */
#takvim.cal-is-fullscreen .daily-timeline-grid {
    max-height: calc(100vh - 240px) !important;
}

/* Aylık layout fullscreen'de daha büyük */
#takvim.cal-is-fullscreen .calendar-layout {
    height: calc(100vh - 140px);
}
#takvim.cal-is-fullscreen .calendar-left,
#takvim.cal-is-fullscreen .calendar-right {
    height: 100%;
    overflow-y: auto;
}
#takvim.cal-is-fullscreen .event-list-wrapper {
    max-height: calc(100vh - 380px);
    overflow-y: auto;
}

/* Arka plan blob'ları fullscreen'de görünsün */
body.has-cal-fullscreen .background-blobs {
    z-index: 9989;
}

/* Çıkış animasyonu */
@keyframes calFsIn {
    from { opacity: 0; }
    to   { opacity: 1; }
}

/* Pürüzsüz geçiş: normal modda transition yok, fullscreen açılırken JS yönetir */
#takvim {
    transition: none !important;
}
@keyframes calFsOpen {
    0%   { opacity: 0; transform: scale(0.75); }
    100% { opacity: 1; transform: scale(1); }
}
@keyframes calFsClose {
    0%   { opacity: 1; transform: scale(1) translateY(0px);    filter: blur(0px);   }
    30%  { opacity: 0.9; transform: scale(0.98) translateY(6px);  filter: blur(2px);  }
    70%  { opacity: 0.4; transform: scale(0.93) translateY(18px); filter: blur(10px); }
    100% { opacity: 0;   transform: scale(0.88) translateY(30px); filter: blur(20px); }
}

#takvim.cal-is-fullscreen {
    animation: calFsOpen 1.1s cubic-bezier(0.16, 1, 0.3, 1) forwards !important;
}
#takvim.cal-is-fullscreen.cal-is-closing {
    animation: calFsClose 0.85s cubic-bezier(0.4, 0, 1, 1) forwards !important;
}

body.has-cal-fullscreen .app-container {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

/* Büyütme ekranında görünürlük */
#takvim.cal-is-fullscreen {
    position: fixed !important;
    top: 0 !important; left: 0 !important;
    width: 100vw !important; height: 100vh !important;
    z-index: 9999 !important;
    background: #0f0c29 !important;
    padding: 30px !important;
    display: flex !important;
    flex-direction: column !important;
    opacity: 1;
    visibility: visible;
}

/* ================================================================
   TAKVİM TAM EKRAN MODU - KESİN ÇÖZÜM
   ================================================================ */

/* 1. Görünmez Duvarı Yık: Kapsayıcı filtrelerini kapat ki takvim dışarı çıkabilsin */
body.has-cal-fullscreen .app-container {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    transform: none !important;
}

/* 2. Takvimi Tüm Ekrana Sabitle ve Tıklanabilir Hale Getir */
#takvim.cal-is-fullscreen {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    max-width: 100vw !important;
    max-height: 100vh !important;
    z-index: 99999 !important; /* Her şeyin üstüne çıkarır, tıklanmayı garanti eder */
    background: #0f0c29 !important; /* Arka planı tamamen kapatır */
    padding: 30px 40px !important;
    display: flex !important;
    flex-direction: column !important;
    margin: 0 !important;
    border-radius: 0 !important;
    pointer-events: auto !important; /* Tıklamaları zorla aktifleştirir */
}

#takvim.cal-is-fullscreen .premium-cal-toolbar {
    flex-shrink: 0 !important;
    margin-bottom: 20px !important;
}

/* 4. İçerik Alanlarını Esnek Yaparak Tüm Ekranı Doldurt */
#takvim.cal-is-fullscreen .cal-view-panel.active {
    display: flex !important;
    flex-direction: column !important;
    flex: 1 !important;
    min-height: 0 !important;
}

#takvim.cal-is-fullscreen .calendar-layout {
    display: flex !important;
    flex: 1 !important;
    min-height: 0 !important;
    gap: 20px !important;
}

#takvim.cal-is-fullscreen .calendar-left,
#takvim.cal-is-fullscreen .calendar-right {
    flex: 1 !important;
    height: 100% !important;
    overflow-y: auto !important;
}

#takvim.cal-is-fullscreen .weekly-cal-wrapper,
#takvim.cal-is-fullscreen .daily-cal-wrapper {
    flex: 1 !important;
    display: flex !important;
    flex-direction: column !important;
    min-height: 0 !important;
}

#takvim.cal-is-fullscreen .weekly-grid-inner,
#takvim.cal-is-fullscreen .daily-timeline-grid,
#takvim.cal-is-fullscreen .event-list-wrapper { 
    flex: 1 !important;
    max-height: none !important;
    height: auto !important;
    overflow-y: auto !important;
}

/* ================================================================
   İSTATİSTİKLER — GELİŞMİŞ PANEL
   ================================================================ */

/* Filtre Barı */
.stats-filter-bar {
    display: flex;
    gap: 8px;
    padding: 6px;
    border-radius: 14px;
    margin-bottom: 16px;
    width: fit-content;
}
.stats-filter-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-family: 'Inter', sans-serif;
    font-size: 13px;
    font-weight: 500;
    padding: 8px 18px;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.25s ease;
}
.stats-filter-btn:hover { background: rgba(255,255,255,0.08); color: #fff; }
.stats-filter-btn.active { background: var(--primary-color); color: #fff; box-shadow: 0 4px 12px rgba(212,144,14,0.4); }

/* Üst Satır (artık sadece mini kart grupları) */
.stats-top-row {
    margin-bottom: 16px;
}

/* Özet şeridi: Skor kartı + Hero metrikler yan yana */
.stats-summary-row {
    display: grid;
    grid-template-columns: 280px 1fr;
    gap: 16px;
    margin-bottom: 20px;
    align-items: stretch;
}
.stats-summary-row .stats-hero-row {
    margin-bottom: 0;
}

/* Üretkenlik Skoru Kartı */
.productivity-score-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 16px 20px;
    gap: 10px;
    text-align: center;
    position: relative;
}
.score-ring-wrapper {
    position: relative;
    width: 100px;
    height: 100px;
}
.score-ring {
    width: 100px;
    height: 100px;
    transform: rotate(-90deg);
}
.score-ring-bg {
    fill: none;
    stroke: rgba(255,255,255,0.06);
    stroke-width: 10;
}
.score-ring-fill {
    fill: none;
    stroke: url(#scoreGradient);
    stroke-width: 10;
    stroke-linecap: round;
    transition: stroke-dashoffset 1.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.score-ring-inner {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}
.score-value {
    font-size: 26px;
    font-weight: 700;
    color: #fff;
    line-height: 1;
}
.score-label {
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 2px;
}
.score-meta h3 {
    font-size: 15px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 6px;
}
.score-meta p {
    font-size: 12px;
    color: var(--text-muted);
    line-height: 1.5;
    margin-bottom: 10px;
}
.score-badges {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    justify-content: center;
}
.score-badge {
    font-size: 10px;
    padding: 3px 9px;
    border-radius: 20px;
    font-weight: 600;
}

/* Skor "Neden?" açıklaması */
.score-title-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    margin-bottom: 6px;
}
.score-title-row h3 { margin-bottom: 0; }
.score-why-btn {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    color: var(--text-muted);
    font-size: 10px;
    font-weight: 600;
    padding: 3px 9px;
    border-radius: 20px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    transition: background 0.2s ease, color 0.2s ease;
}
.score-why-btn:hover {
    background: rgba(255,255,255,0.12);
    color: #fff;
}
/* Popover: layoutu itmeden, kartın sağında yüzen katman olarak açılır */
.score-breakdown {
    position: absolute;
    top: 0;
    left: calc(100% + 12px);
    width: 240px;
    text-align: left;
    margin-top: 0;
    padding: 14px;
    border-top: none;
    display: flex;
    flex-direction: column;
    gap: 8px;
    background: rgba(18, 14, 36, 0.98);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 12px;
    box-shadow: 0 16px 36px rgba(0,0,0,0.55);
    z-index: 40;
    animation: scoreBreakdownIn 0.16s ease;
}
@keyframes scoreBreakdownIn {
    from { opacity: 0; transform: translateX(-4px); }
    to { opacity: 1; transform: translateX(0); }
}
.score-breakdown-row {
    display: grid;
    grid-template-columns: 1fr 2fr auto;
    align-items: center;
    gap: 8px;
}
.score-breakdown-label {
    font-size: 11px;
    color: var(--text-muted);
}
.score-breakdown-label em {
    font-style: normal;
    opacity: 0.7;
}
.score-breakdown-bar-track {
    height: 6px;
    border-radius: 4px;
    background: rgba(255,255,255,0.08);
    overflow: hidden;
}
.score-breakdown-bar-fill {
    height: 100%;
    width: 0%;
    border-radius: 4px;
    transition: width 0.5s ease;
}
.score-breakdown-val {
    font-size: 11px;
    font-weight: 600;
    color: #fff;
    min-width: 28px;
    text-align: right;
}

/* Düşük örneklem güven uyarısı */
.stat-confidence-flag {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 10px;
    color: var(--text-muted);
    margin-top: 3px;
    cursor: help;
}

/* Mini Kartlar Grid — 3 Grup */
.stats-mini-cards {
    display: flex;
    flex-direction: column;
    gap: 16px;
}
.mini-cards-group-title {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--text-muted);
    margin-bottom: 8px;
}
.mini-cards-group-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 12px;
}
.stats-mini-cards .stat-card {
    padding: 16px;
    display: flex;
    align-items: center;
    gap: 12px;
    border-radius: 16px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.stats-mini-cards .stat-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}
.stat-trend {
    font-size: 11px;
    margin-top: 3px;
    display: block;
}
.stat-trend.up { color: #2ed573; }
.stat-trend.down { color: #ff4757; }
.stat-trend.neutral { color: var(--text-muted); }

/* Isı Haritası */
.heatmap-card {
    padding: 14px 16px;
    margin-bottom: 12px;
}
.heatmap-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 16px;
}
.heatmap-header h3 {
    font-size: 15px;
    font-weight: 600;
    color: #fff;
    display: flex;
    align-items: center;
    gap: 8px;
}
.heatmap-subtitle {
    font-size: 11px;
    color: var(--text-muted);
    font-weight: 400;
    margin-left: 4px;
}
.heatmap-legend {
    display: flex;
    align-items: center;
    gap: 6px;
}
.heatmap-legend-cells {
    display: flex;
    gap: 3px;
}
.hm-cell {
    width: 12px;
    height: 12px;
    border-radius: 3px;
}
.heatmap-body {
    display: flex;
    gap: 8px;
    align-items: flex-start;
}
.heatmap-days-label span {
    font-size: 10px;
    color: var(--text-muted);
    height: 28px;
    display: flex;
    align-items: center;
}

.hm-day {
    width: 100%;
    aspect-ratio: 1;
    border-radius: 3px;
    background: rgba(255,255,255,0.04);
    cursor: pointer;
    transition: transform 0.15s, opacity 0.15s;
    position: relative;
}
.hm-day[data-level="1"] { background: rgba(212,144,14,0.2); }
.hm-day[data-level="2"] { background: rgba(212,144,14,0.4); }
.hm-day[data-level="3"] { background: rgba(212,144,14,0.65); }
.hm-day[data-level="4"] { background: rgba(212,144,14,0.85); }
.hm-day[data-level="5"] { background: #D4900E; box-shadow: 0 0 8px rgba(212,144,14,0.6); }

/* Streak Kartları */








.streak-dots { display: flex; gap: 4px; flex-wrap: wrap; }
.streak-dot {
    width: 10px; height: 10px;
    border-radius: 50%;
    background: rgba(255,255,255,0.08);
}
.streak-dot.active { background: #ff9f43; box-shadow: 0 0 6px rgba(255,159,67,0.5); }




.mini-bar-fill.purple { background: linear-gradient(90deg, #D4900E, #D4900E); }
.mini-bar-fill.green  { background: linear-gradient(90deg, #00b894, #2ed573); }

/* Grafikler Satırı */
.stats-charts-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}

/* Responsive */
@media (max-width: 900px) {
    .stats-summary-row { grid-template-columns: 1fr; }
    .mini-cards-group-row { grid-template-columns: repeat(2, 1fr); }
    /* Dar ekranda kartın sağında yer olmayabilir, popover alta düşsün */
    .score-breakdown {
        top: calc(100% + 8px);
        left: 0;
        width: auto;
        right: 0;
    }
}
@media (max-width: 600px) {
    .stats-hero-row { grid-template-columns: 1fr; }
    .mini-cards-group-row { grid-template-columns: 1fr; }
    
}

/* ===== CTRL+K KOMUT PALETİ ===== */
.cmd-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(6px);
    z-index: 99999;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding-top: 12vh;
    animation: cmdFadeIn 0.15s ease;
}

.cmd-overlay.hidden { display: none; }

@keyframes cmdFadeIn {
    from { opacity: 0; }
    to   { opacity: 1; }
}

.cmd-palette {
    width: 100%;
    max-width: 600px;
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 25px 60px rgba(0,0,0,0.6), 0 0 0 1px rgba(212,144,14,0.3);
    animation: cmdSlideIn 0.18s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes cmdSlideIn {
    from { opacity: 0; transform: translateY(-20px) scale(0.97); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
}

.cmd-search-row {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 16px 20px;
    border-bottom: 1px solid var(--glass-border);
}

.cmd-search-icon {
    color: var(--text-muted);
    font-size: 16px;
    flex-shrink: 0;
}

.cmd-input {
    flex: 1;
    background: transparent;
    border: none;
    outline: none;
    color: #fff;
    font-size: 16px;
    font-family: 'Inter', sans-serif;
    caret-color: var(--primary-color);
}

.cmd-esc-badge {
    background: rgba(255,255,255,0.07);
    border: 1px solid var(--glass-border);
    border-radius: 6px;
    padding: 3px 8px;
    font-size: 11px;
    color: var(--text-muted);
    font-family: 'Inter', sans-serif;
    flex-shrink: 0;
}

.cmd-results {
    max-height: 380px;
    overflow-y: auto;
    padding: 8px;
}

.cmd-results::-webkit-scrollbar { width: 4px; }
.cmd-results::-webkit-scrollbar-track { background: transparent; }
.cmd-results::-webkit-scrollbar-thumb { background: var(--glass-border); border-radius: 4px; }

.cmd-group-label {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--text-muted);
    padding: 10px 12px 5px;
}

.cmd-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    border-radius: 10px;
    cursor: pointer;
    transition: background 0.15s ease;
    color: #fff;
    font-size: 14px;
}

.cmd-item:hover, .cmd-item.active {
    background: rgba(212,144,14,0.25);
}

.cmd-item-icon {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    flex-shrink: 0;
}

.cmd-item-text { flex: 1; }
.cmd-item-title { font-size: 13px; font-weight: 500; }
.cmd-item-sub   { font-size: 11px; color: var(--text-muted); margin-top: 1px; }

.cmd-item-badge {
    font-size: 10px;
    padding: 2px 8px;
    border-radius: 20px;
    font-weight: 600;
    white-space: nowrap;
}

.cmd-empty {
    text-align: center;
    padding: 40px 20px;
    color: var(--text-muted);
    font-size: 13px;
}

.cmd-empty i { font-size: 28px; margin-bottom: 10px; display: block; opacity: 0.4; }

.cmd-footer {
    display: flex;
    gap: 16px;
    padding: 10px 16px;
    border-top: 1px solid var(--glass-border);
    background: rgba(0,0,0,0.15);
}

.cmd-footer span {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 11px;
    color: var(--text-muted);
}

.cmd-footer kbd {
    background: rgba(255,255,255,0.07);
    border: 1px solid var(--glass-border);
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 10px;
    color: var(--text-muted);
    font-family: 'Inter', sans-serif;
}

/* ==========================================================================
   premium istatistik sekme ve grup stilleri
   ========================================================================== */

/* Grafik sekmelerinin genel kutusu */


/* Grafik sekme butonları */
.chart-tab-btn {
    border: none;
    background: transparent;
    color: var(--text-muted);
