/* === KİTAP SIRTLARI === */
.book-spine {
    position: relative;
    border-radius: 2px 5px 5px 2px;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    padding-bottom: 12px;
    flex-shrink: 0;
    overflow: hidden;
    transition:
        transform 0.28s cubic-bezier(0.34, 1.56, 0.64, 1),
        box-shadow 0.28s ease,
        filter 0.28s ease;
    transform-origin: bottom center;
    z-index: 1;
    box-shadow:
        2px 0 6px rgba(0,0,0,0.4),
        inset -2px 0 4px rgba(0,0,0,0.2);
}

.book-spine:hover {
    transform: translateY(-18px) scale(1.06);
    box-shadow:
        4px 0 20px rgba(0,0,0,0.7),
        0 -8px 30px var(--book-glow, rgba(212,144,14,0.35)),
        inset -2px 0 4px rgba(0,0,0,0.2);
    filter: brightness(1.18);
    z-index: 20;
}

/* Kitap sol parlaklık şeridi */
.book-spine::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 30%;
    height: 100%;
    background: linear-gradient(90deg,
        rgba(255,255,255,0.18) 0%,
        rgba(255,255,255,0.06) 60%,
        transparent 100%);
    border-radius: 2px 0 0 2px;
    pointer-events: none;
}

/* Kitap üst yansıması */
.book-spine::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 12px;
    background: linear-gradient(180deg,
        rgba(255,255,255,0.15) 0%,
        transparent 100%);
    pointer-events: none;
}









