/* --- DIŞ AHŞAP ÇERÇEVE (library-grand-container) --- */
.library-grand-container {
    position: relative;
    padding: 20px;
    border-radius: 14px;

    /* Ahşap damar dokusu — katmanlı */
    background:
        repeating-linear-gradient(
            172deg,
            transparent 0px, transparent 5px,
            rgba(0,0,0,0.09) 5px, rgba(0,0,0,0.09) 6px
        ),
        repeating-linear-gradient(
            86deg,
            transparent 0px, transparent 52px,
            rgba(255,255,255,0.018) 52px, rgba(255,255,255,0.018) 53px
        ),
        linear-gradient(155deg, #4e2c14 0%, #2e1a0a 30%, #3d2010 65%, #1e0c06 100%);

    /* box-shadow ile üçlü çerçeve efekti (border-image radius'u bozar, bu yöntem bozmuyor) */
    box-shadow:
        0 0 0 1px #120804,
        0 0 0 4px #5c3418,
        0 0 0 6px #120804,
        0 0 0 8px #3d2010,
        0 50px 100px rgba(0,0,0,0.97),
        0 25px 50px rgba(0,0,0,0.8),
        inset 0 2px 3px rgba(255,210,130,0.18),
        inset 0 -3px 5px rgba(0,0,0,0.95);

    overflow: hidden;
}

/* Üst kornis şeridi */
.library-grand-container::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 20px;
    border-radius: 14px 14px 0 0;
    background: linear-gradient(180deg,
        #7a4828 0%,
        #5c3418 40%,
        #3d2010 100%
    );
    box-shadow:
        0 3px 8px rgba(0,0,0,0.7),
        inset 0 1px 0 rgba(255,220,140,0.28),
        inset 0 2px 0 rgba(255,220,140,0.08);
    z-index: 1;
    pointer-events: none;
}

/* Alt taban şeridi */
.library-grand-container::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 20px;
    border-radius: 0 0 14px 14px;
    background: linear-gradient(0deg,
        #0a0503 0%,
        #1e0e06 60%,
        #3a2010 100%
    );
    box-shadow:
        inset 0 -1px 0 rgba(0,0,0,0.98),
        inset 0 1px 2px rgba(0,0,0,0.6);
    z-index: 1;
    pointer-events: none;
}

/* Zemin — derin ahşap parke gölgesi */
.library-room::after {
    height: 32px !important;
    background: linear-gradient(180deg,
        rgba(20,10,4,0.1) 0%,
        rgba(8,4,2,0.98) 100%
    ) !important;
    border-radius: 0 0 6px 6px !important;
    z-index: 0 !important;
    pointer-events: none !important;
}

