/* ── Takvim / Heatmap Görünümü ── */
.library-calendar-view { width: 100%; margin-top: 12px; }
.library-calendar-view.hidden { display: none; }
#gunluk .library-calendar-view {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}
#gunluk .library-calendar-view.hidden { display: none; }

.library-calendar-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    grid-auto-rows: minmax(0, 1fr);
    gap: 6px;
    padding: 16px;
    width: 100%;
    flex: 1;
    min-height: 0;
    box-sizing: border-box;
    background: rgba(255,255,255,0.02);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 14px;
}
.cal-day-header {
    text-align: center;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: rgba(255,255,255,0.25);
    padding-bottom: 6px;
}
/* Not: .cal-day sınıfı başka bir takvim bileşeniyle paylaşılıyor (bkz. satır ~3776,
   aspect-ratio:1 tanımlıyor) — burada .library-calendar-grid ile scope edip o kuralı
   açıkça sıfırlıyoruz, aksi halde hücreler kare olmaya zorlanıp satır yüksekliğini taşıyordu. */
.library-calendar-grid .cal-day {
    aspect-ratio: auto;
    overflow: visible;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.15s, box-shadow 0.15s;
    position: relative;
    border: 1px solid transparent;
    min-height: 0;
    min-width: 0;
}
.library-calendar-grid .cal-day:hover { transform: scale(1.03); z-index: 2; }
.library-calendar-grid .cal-day.cal-empty { visibility: hidden; }
.library-calendar-grid .cal-day.cal-future {
    background: rgba(255,255,255,0.02);
    color: rgba(255,255,255,0.15);
    cursor: not-allowed;
    border-color: rgba(255,255,255,0.04);
}
.library-calendar-grid .cal-day.cal-past-empty {
    background: rgba(255,255,255,0.04);
    color: rgba(255,255,255,0.3);
    border-color: rgba(255,255,255,0.05);
}
.library-calendar-grid .cal-day.cal-past-empty:hover { background: rgba(255,255,255,0.08); color: rgba(255,255,255,0.5); }
.library-calendar-grid .cal-day.cal-filled {
    background: rgba(212,144,14,0.18);
    color: #f0c060;
    border-color: rgba(212,144,14,0.3);
    box-shadow: 0 0 8px rgba(212,144,14,0.15);
}
.library-calendar-grid .cal-day.cal-filled:hover { background: rgba(212,144,14,0.28); box-shadow: 0 0 16px rgba(212,144,14,0.3); }
.library-calendar-grid .cal-day.cal-today {
    background: rgba(212,144,14,0.12);
    color: var(--primary-color);
    border: 1.5px solid var(--primary-color);
    box-shadow: 0 0 12px rgba(212,144,14,0.35);
}
.library-calendar-grid .cal-day.cal-filled.cal-today { background: rgba(212,144,14,0.3); }
.library-calendar-grid .cal-day-num { line-height: 1; }
.library-calendar-grid .cal-dot {
    width: 3px; height: 3px;
    border-radius: 50%;
    background: currentColor;
    margin-top: 2px;
    opacity: 0.7;
}
.library-calendar-grid .cal-day.cal-past-empty .cal-dot { display: none; }
.library-calendar-grid .cal-day.cal-future .cal-dot { display: none; }

