/* Boş bırakılan girdi alanına eklenecek parlamalı kırmızı border sınıfı */
.premium-input-error {
    border-color: #ff4757 !important;
    background: rgba(255, 71, 87, 0.05) !important;
    box-shadow: 0 0 15px rgba(255, 71, 87, 0.35), 
                inset 0 0 10px rgba(255, 71, 87, 0.1) !important;
    animation: premiumInputShake 0.45s cubic-bezier(.36,.07,.19,.97) both;
    transform: translate3d(0, 0, 0);
    backface-visibility: hidden;
    perspective: 1000px;
}

/* Akıcı ve doğrusal premium titreme (shake) efekti */
@keyframes premiumInputShake {
    10%, 90% { transform: translate3d(-2px, 0, 0); }
    20%, 80% { transform: translate3d(4px, 0, 0); }
    30%, 50%, 70% { transform: translate3d(-6px, 0, 0); }
    40%, 64% { transform: translate3d(6px, 0, 0); }
}

/* ================================================================
   [PREMIUM LIBRARY] KİTAP SIRTI VE GLASSMORPHIC TOOLTIP TASARIMI
   ================================================================ */

/* 1. Kitapların genel konteyner ayarları ve 3D Hover efekti */


/* Kitap hover olduğunda pürüzsüzce yukarı ve öne kayar */


/* 2. Kitap Sırtı Yazı Tasarımı (26 HAZ ve Gün adı düzeni) */




/* 3. İpek Ayraç Şeridi (Hover durumunda yukarı fırlayan kırmızı şerit) */




/* 4. Buzlu Cam (Glassmorphic) Premium Bilgi Kartı */
.book-premium-tooltip {
    position: absolute !important;
    bottom: calc(100% + 14px) !important;
    left: 50% !important;
    transform: translateX(-50%) translateY(10px) scale(0.95) !important;
    width: 200px !important;
    /* Parşömen / eski kitap sayfası estetiği */
    background:
        linear-gradient(160deg,
            rgba(36, 22, 10, 0.97) 0%,
            rgba(24, 14, 6, 0.99) 100%
        ) !important;
    backdrop-filter: blur(18px) saturate(1.4) !important;
    -webkit-backdrop-filter: blur(18px) saturate(1.4) !important;
    border: 1px solid rgba(212, 165, 60, 0.28) !important;
    border-top: 2px solid rgba(220, 175, 70, 0.75) !important;
    border-radius: 14px !important;
    padding: 14px 15px 12px !important;
    color: #ede0c8 !important;
    box-shadow:
        0 24px 48px rgba(0, 0, 0, 0.88),
        0 8px 16px rgba(0, 0, 0, 0.60),
        0 0 0 1px rgba(0, 0, 0, 0.55),
        inset 0 1px 0 rgba(255, 230, 130, 0.10),
        inset 0 0 20px rgba(0, 0, 0, 0.20) !important;
    opacity: 0 !important;
    visibility: hidden !important;
    transition:
        opacity 0.20s ease,
        transform 0.20s cubic-bezier(0.34, 1.4, 0.64, 1),
        visibility 0.20s ease !important;
    z-index: 999999 !important;
    pointer-events: none !important;
    text-align: left !important;
}

/* Yatay çizgi süsü — eski kitap sayfası hissi */
.book-premium-tooltip .bpt-divider {
    height: 1px !important;
    margin: 8px 0 !important;
    background: linear-gradient(90deg,
        transparent, rgba(212,165,60,0.3) 20%, rgba(212,165,60,0.3) 80%, transparent
    ) !important;
}

/* Alttan çıkan ok — arka plan rengiyle eşleşen iki katman */
.book-premium-tooltip::after {
    content: '' !important;
    position: absolute !important;
    top: 100% !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    border: 8px solid transparent !important;
    border-top-color: rgba(24, 14, 6, 0.99) !important;
    z-index: 2 !important;
}
.book-premium-tooltip::before {
    content: '' !important;
    position: absolute !important;
    top: calc(100% + 1px) !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    border: 9px solid transparent !important;
    border-top-color: rgba(220, 175, 70, 0.6) !important;
    z-index: 1 !important;
}

/* Hover aktif */
#library-room .bookshelf-book:hover .book-premium-tooltip {
    opacity: 1 !important;
    visibility: visible !important;
    transform: translateX(-50%) translateY(0) scale(1) !important;
}

