.bf-settings-group {
    width: 100%;
    margin-bottom: 16px;
    text-align: left;
}



.bf-settings-toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 9px 0;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    color: #fff;
    font-size: 13px;
}

.bf-settings-toggle-row:last-child {
    border-bottom: none;
}

.bf-switch {
    position: relative;
    display: inline-block;
    width: 40px;
    height: 22px;
    flex-shrink: 0;
}

.bf-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.bf-switch-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background: rgba(255,255,255,0.12);
    border-radius: 22px;
    transition: background 0.2s ease;
}

.bf-switch-slider::before {
    content: "";
    position: absolute;
    height: 16px;
    width: 16px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s ease;
}

.bf-switch input:checked + .bf-switch-slider {
    background: var(--primary-color);
}

.bf-switch input:checked + .bf-switch-slider::before {
    transform: translateX(18px);
}

/* ──────────────────────────────────────────────────────
   YUMUŞAK AŞAMA GEÇİŞ EKRANI — "☕ Mola Zamanı!" / "🧠 Odaklanma Başlıyor!"
   şeklinde tüm overlay'i kısa süreliğine kaplayan splash animasyonu
   ────────────────────────────────────────────────────── */
.bf-phase-transition {
    position: absolute; inset: 0; z-index: 50;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px;
    background: rgba(8, 6, 20, 0.88);
    backdrop-filter: blur(10px);
    opacity: 0; pointer-events: none;
    transition: opacity 0.45s ease;
}
.bf-phase-transition.visible { opacity: 1; pointer-events: auto; }
.bf-phase-transition.hidden { display: none !important; }
.bf-phase-transition-emoji {
    font-size: 64px;
    animation: bfPhaseEmojiPop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.bf-phase-transition-text {
    font-size: 22px; font-weight: 800; color: #fff;
    letter-spacing: 0.3px;
    text-shadow: 0 4px 24px rgba(212,144,14,0.4);
    animation: bfPhaseTextRise 0.5s ease-out 0.1s both;
}
@keyframes bfPhaseEmojiPop {
    0%   { transform: scale(0.3) rotate(-12deg); opacity: 0; }
    60%  { transform: scale(1.18) rotate(4deg); opacity: 1; }
    100% { transform: scale(1) rotate(0deg); opacity: 1; }
}
@keyframes bfPhaseTextRise {
    from { transform: translateY(14px); opacity: 0; }
    to   { transform: translateY(0); opacity: 1; }
}

/* ──────────────────────────────────────────────────────
   GRUP ODAKLANMASI — Bireysel Zamanlayıcı'daki "Odak Modu" (focus-mode-active)
   ve "Hayalet Mod" (ghost-mode-active) davranışlarının birebir aynısı,
   #group-focus-overlay üzerinde uygulanır */
#group-focus-overlay {
    position: fixed;
    inset: 0;
    z-index: 10100;
    display: none;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    background: var(--bg-color, #0b0a17);
    overflow-y: auto;
    padding: 30px 20px;
}
#group-focus-overlay.visible { display: flex; }

#group-focus-overlay.group-focus-mode-active {
    background-color: #05040f;
}

/* Odak modunda sadece başlık metni gizlenir, butonlar kalır */
#group-focus-overlay.group-focus-mode-active .section-header {
    display: flex !important;
    background: transparent !important;
    border-bottom: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}
