    display: block !important;
    opacity: 1 !important;
    visibility: visible !important;
    color: rgba(255, 255, 255, 0.75);
}

#group-focus-overlay.group-focus-mode-active .timer-container {
    transform: scale(1.05);
    transition: all 0.6s ease;
}

/* Odak modunda mola sohbeti her zaman görünebilir (CSS tarafından engellenmez) */
#group-focus-overlay.group-focus-mode-active .cws-break-chat.visible {
    display: flex !important;
}

#group-focus-overlay.group-ghost-mode-active {
    cursor: none !important;
}
/* Ghost modda header tamamen gizli kalır (focus-mode-active'den miras) */
#group-focus-overlay.group-ghost-mode-active .section-header {
    display: none;
}
#group-focus-overlay.group-ghost-mode-active .timer-modes,
#group-focus-overlay.group-ghost-mode-active #gf-round-counter,
#group-focus-overlay.group-ghost-mode-active .timer-controls,
