/* ═══════════════════════════════════════════════
   ☕  MOLA SOHBETİ PANEL
═══════════════════════════════════════════════ */
.cws-break-chat {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    width: min(360px, 92vw);
    max-height: none;
    background: rgba(12, 10, 35, 0.97);
    border: 1px solid rgba(116,185,255,0.25);
    border-left: 1px solid rgba(116,185,255,0.25);
    border-radius: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    box-shadow: -20px 0 60px rgba(0,0,0,0.5), 0 0 0 1px rgba(255,255,255,0.04);
    opacity: 0;
    transform: translateX(100%);
    pointer-events: none;
    transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.34,1.56,0.64,1);
    z-index: 60;
}
.cws-break-chat.visible {
    opacity: 1;
    transform: translateX(0);
    pointer-events: all;
}
.cws-bc-header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 9px 12px;
    background: rgba(116,185,255,0.08);
    border-bottom: 1px solid rgba(116,185,255,0.15);
    flex-shrink: 0;
    cursor: grab;
    user-select: none;
}
.cws-bc-header:active { cursor: grabbing; }
.cws-bc-header-left { display: flex; align-items: center; gap: 8px; }
.cws-bc-dot {
