/* Panel kapsayıcı */
.social-sidebar-panel {
    /* Aynı @media (max-width:420px) bloğu içinde bu selector iki kez tanımlıydı;
       bu blok kaynak sırasında sonra geldiği için tüm ortak özelliklerde zaten
       kazanıyordu — box-sizing/color eski bloktan (aşılmamış tek 2 özellik)
       buraya taşındı, görünür davranış değişmedi. */
    position: fixed;
    top: 0; right: 0;
    width: 360px;
    height: 100vh;
    background: linear-gradient(160deg, rgba(15,12,41,0.97) 0%, rgba(22,18,55,0.97) 100%);
    backdrop-filter: blur(24px);
    -webkit-backdrop-filter: blur(24px);
    border-left: 1px solid rgba(212,144,14,0.2);
    box-shadow: -8px 0 40px rgba(0,0,0,0.5);
    z-index: 9990;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    transition: transform 0.38s cubic-bezier(0.4,0,0.2,1), opacity 0.3s ease;
    box-sizing: border-box;
    color: #ffffff;
}
.social-sidebar-panel.hidden-sidebar {
    transform: translateX(110%);
    opacity: 0;
    pointer-events: none;
}

