#dc-chat-area.dc-view-group-panel > *:not(#dc-group-panel-view) { display: none !important; }
#dc-chat-area.dc-view-group-panel > #dc-group-panel-view { display: block; }
/* Grup paneli chat alanının tamamını kullanır; hub'daki köşe/kenar kuralları sıfırlanır */
#dc-group-panel-view { padding: 0; }

#dc-group-panel-view .groups-hub-panel {
    width: 100%;
    height: 100%;
    margin: 0;
    border-radius: 0 !important;
