#dc-conn-banner.show.offline { border-color: rgba(255,71,87,0.55); }
#dc-conn-banner.show.online  { border-color: rgba(46,213,115,0.55); }

#dc-undo-toast {
    position: fixed;
    bottom: 30px;
    left: 50%;
    transform: translateX(-50%) translateY(20px);
    background: rgba(15,12,41,0.95);
    border: 1px solid rgba(212,144,14,0.3);
    color: #fff;
    font-size: 13px;
    padding: 10px 12px 10px 18px;
