/* ── Mesaj metni biçimlendirme (markdown/link) ── */
.chat-inline-code {
    background: rgba(0,0,0,0.35);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 4px;
    padding: 1px 5px;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
    font-size: 12px;
}
.chat-msg-link {
    color: #74b9ff;
    text-decoration: underline;
    word-break: break-all;
}
.dc-msg-edited-tag {
    font-size: 10px;
    color: rgba(255,255,255,0.3);
    font-style: italic;
    margin-left: 4px;
}

/* ── "Yazıyor..." göstergesi ── */
.dc-typing-indicator {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: rgba(255,255,255,0.55);
    font-style: italic;
}
.dc-typing-dots {
    display: inline-flex;
    gap: 3px;
}
.dc-typing-dots span {
    width: 4px; height: 4px; border-radius: 50%;
