.dc-recent-convo-pin-icon {
    font-size: 10px;
    color: rgba(255,255,255,0.55);
    margin-right: 4px;
    transform: rotate(35deg);
    display: inline-block;
}
.dc-recent-convo-mute-icon {
    font-size: 10px;
    color: rgba(255,255,255,0.3);
    margin-left: 6px;
}
.dc-convo-context-menu {
    position: fixed;
    z-index: 100003;
    background: rgba(22,18,55,0.98);
    border: 1px solid rgba(212,144,14,0.3);
    border-radius: 10px;
    padding: 6px;
    box-shadow: 0 8px 32px rgba(0,0,0,0.5);
