    text-align: left;
    padding: 8px 10px;
    border-radius: 8px;
    cursor: pointer;
}
.dc-convo-context-menu button:hover { background: rgba(212,144,14,0.2); }
.dc-convo-context-menu button i { width: 14px; color: rgba(255,255,255,0.5); }

/* ── Sohbet içi arama çubuğu ── */
.dc-chat-search-bar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    background: rgba(0,0,0,0.2);
    border-bottom: 1px solid rgba(255,255,255,0.04);
    flex-shrink: 0;
}
.dc-chat-search-icon { color: rgba(255,255,255,0.35); font-size: 12px; }
.dc-chat-search-input {
    flex: 1;
    background: transparent;
    border: none;
    outline: none;
    color: #fff;
    font-size: 13px;
}
.dc-chat-search-input::placeholder { color: rgba(255,255,255,0.3); }
.dc-chat-search-count {
    font-size: 11px;
    color: rgba(255,255,255,0.4);
    white-space: nowrap;
}
.dc-msg-search-dim { opacity: 0.35; transition: opacity 0.15s ease; }
.dc-dm-msg-row.dc-msg-search-match .dc-msg-text {
    outline: 2px solid rgba(254,202,87,0.5);
}
.dc-dm-msg-row.dc-msg-search-active .dc-msg-text {
    outline: 2px solid #feca57;
    box-shadow: 0 0 12px rgba(254,202,87,0.4);
}
@keyframes dcMsgFlash {
    0%   { background-color: rgba(254,202,87,0.35); }
    100% { background-color: transparent; }
}
.dc-dm-msg-row.dc-msg-flash .dc-msg-text {
    animation: dcMsgFlash 1.2s ease-out;
}

/* ── Eski mesajları geç yükle butonu ── */
.dc-load-more-btn {
    display: block;
    margin: 4px auto 12px;
    padding: 6px 16px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 20px;
    color: rgba(255,255,255,0.6);
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
}
.dc-load-more-btn:hover { background: rgba(212,144,14,0.2); color: #fff; }

/* ── "Yeni mesajlar" ayıracı ── */
.dc-unread-divider {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 10px 0;
}
.dc-unread-divider-line {
    flex: 1;
    height: 1px;
    background: rgba(255,71,87,0.35);
}
.dc-unread-divider-label {
    font-size: 11px;
    font-weight: 700;
    color: #ff7675;
    white-space: nowrap;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* ── Okundu bilgisi (baloncuğun altındaki tikler) ── */
.dc-read-receipt {
    position: absolute;
    bottom: -14px;
    right: 2px;
    font-size: 10px;
}
.dc-read-receipt.seen { color: #74b9ff; }
.dc-read-receipt.sent { color: rgba(255,255,255,0.25); }

/* ── Grup "okundu" bilgisi & okuyanlar listesi ── */
.dc-group-read-receipt:hover { color: rgba(255,255,255,0.6); }
.dc-readers-popover {
    position: fixed; inset: 0;
    background: rgba(0,0,0,0.4);
    display: flex; align-items: center; justify-content: center;
    z-index: 10000;
    opacity: 0; transition: opacity 0.15s;
}
.dc-readers-popover.show { opacity: 1; }
.dc-readers-popover-inner {
    background: rgba(22,18,55,0.98);
    border: 1px solid rgba(212,144,14,0.3);
    border-radius: 14px;
    padding: 16px;
    width: 240px;
    max-height: 320px;
    overflow-y: auto;
    transform: scale(0.95);
    transition: transform 0.15s;
}
.dc-readers-popover.show .dc-readers-popover-inner { transform: scale(1); }
.dc-readers-popover-title {
    font-size: 13px; font-weight: 700; color: #fff;
    margin-bottom: 10px;
}
.dc-readers-popover-list { display: flex; flex-direction: column; gap: 8px; }
.dc-readers-popover-item { display: flex; align-items: center; gap: 8px; }
.dc-readers-popover-avatar { width: 28px; height: 28px; border-radius: 50%; object-fit: cover; }
.dc-readers-popover-name { font-size: 12px; color: rgba(255,255,255,0.8); }

/* ── Özel onay penceresi (confirm() yerine) ── */
.dc-confirm-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100002;
    backdrop-filter: blur(3px);
    opacity: 0;
    transition: opacity 0.16s ease;
}
.dc-confirm-modal-overlay.show { opacity: 1; }
.dc-confirm-modal {
    background: rgba(22,18,55,0.98);
    border: 1px solid rgba(212,144,14,0.3);
    border-radius: 16px;
    width: 300px;
    padding: 24px 22px 18px;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    box-shadow: 0 12px 48px rgba(0,0,0,0.55);
    transform: scale(0.92) translateY(8px);
    transition: transform 0.18s cubic-bezier(.34,1.56,.64,1);
}
.dc-confirm-modal-overlay.show .dc-confirm-modal { transform: scale(1) translateY(0); }
.dc-confirm-modal-icon {
    width: 52px; height: 52px; border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 20px;
    background: rgba(212,144,14,0.15);
    color: rgba(255,255,255,0.55);
    margin-bottom: 14px;
}
.dc-confirm-modal-icon.danger {
    background: rgba(255,71,87,0.15);
    color: #ff7675;
}
.dc-confirm-modal-title {
    font-size: 16px; font-weight: 700; color: #fff;
    margin-bottom: 8px;
}
.dc-confirm-modal-message {
    font-size: 13px; color: rgba(255,255,255,0.55);
    line-height: 1.5;
    margin-bottom: 20px;
}
.dc-confirm-modal-actions {
    display: flex; gap: 10px; width: 100%;
}
.dc-confirm-btn {
    flex: 1;
    padding: 10px 0;
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.08);
    background: rgba(255,255,255,0.06);
    color: #fff;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s, transform 0.1s;
}
.dc-confirm-btn:hover { transform: translateY(-1px); }
.dc-confirm-btn.dc-confirm-cancel:hover { background: rgba(255,255,255,0.12); }
.dc-confirm-btn.dc-confirm-ok {
    background: rgba(212,144,14,0.85);
    border-color: transparent;
}
.dc-confirm-btn.dc-confirm-ok:hover { background: #D4900E; }
.dc-confirm-btn.dc-confirm-ok.danger {
    background: rgba(255,71,87,0.85);
}
.dc-confirm-btn.dc-confirm-ok.danger:hover { background: #ff4757; }

/* Prodüktivite popup */
#productivity-preview-popup {
    background: rgba(22,18,55,0.95);
    border: 1px solid rgba(212,144,14,0.3);
    border-radius: 12px;
    margin: 6px 14px;
