/* ── GRUP AĞACI ( tarzı metin listesi) ── */
.dc-groups-tree {
    padding: 0 8px;
    margin-bottom: 4px;
  }
  
  .dc-tree-group {
    margin-bottom: 2px;
  }
  
  .dc-tree-group-header {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 5px 6px;
    border-radius: 6px;
    cursor: pointer;
    color: rgba(255,255,255,0.55);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    user-select: none;
    transition: color 0.15s, background 0.15s;
  }
  .dc-tree-group-header:hover {
    color: #fff;
    background: rgba(255,255,255,0.05);
  }
  .dc-tree-group-header .dc-tree-arrow {
    font-size: 9px;
    transition: transform 0.2s;
    flex-shrink: 0;
    color: rgba(255,255,255,0.35);
  }
  .dc-tree-group-header.open .dc-tree-arrow {
    transform: rotate(90deg);
  }
  .dc-tree-group-header.active-group {
    color: #fff;
    background: rgba(212,144,14,0.2);
  }
  
  .dc-tree-channels {
    display: none;
    flex-direction: column;
    gap: 1px;
    padding-left: 14px;
    margin-top: 1px;
  }
  .dc-tree-channels.open {
    display: flex;
  }
  
  .dc-tree-channel {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 8px;
    border-radius: 5px;
    cursor: pointer;
    color: rgba(255,255,255,0.45);
    font-size: 13px;
    transition: color 0.15s, background 0.15s;
  }
  .dc-tree-channel:hover {
    color: rgba(255,255,255,0.85);
    background: rgba(255,255,255,0.06);
  }
  .dc-tree-channel.active {
    color: #fff;
    background: rgba(212,144,14,0.3);
  }
  .dc-tree-channel .dc-tree-hash {
    font-size: 12px;
    color: rgba(255,255,255,0.3);
    flex-shrink: 0;
  }

