/* Rol Etiketlerinin Genel Tasarımı */
.role-badge {
    font-size: 8px;
    padding: 1px 4px;
    border-radius: 3px;
    font-weight: 600;
    text-transform: none;
    letter-spacing: 0;
    margin-left: 5px;
    display: inline-flex;
    align-items: center;
    line-height: 1.4;
    vertical-align: middle;
}

/* Admin (Kırmızı Etiket) */
.role-badge.role-admin {
    background: rgba(255, 71, 87, 0.15) !important;
    color: #ff4757 !important;
    border: 1px solid rgba(255, 71, 87, 0.3) !important;
}

/* Moderatör (Mavi Etiket) */
.role-badge.role-moderator {
    background: rgba(9, 132, 227, 0.15) !important;
    color: #0984e3 !important;
    border: 1px solid rgba(9, 132, 227, 0.3) !important;
}

/* Üye (Yeşil/Gri Etiket) */
.role-badge.role-member {
    background: rgba(46, 213, 115, 0.15) !important;
    color: #2ed573 !important;
    border: 1px solid rgba(46, 213, 115, 0.3) !important;
}

/* Özel Rol (Mor Etiket) */
.role-badge.role-custom {
    background: rgba(212, 144, 14, 0.15) !important;
