/* ─── Yetki Yönetimi: Sekmeler & Rol Oluşturma ─── */
.gm-tabs {
    display: flex;
    gap: 6px;
    margin-bottom: 14px;
    border-bottom: 1px solid rgba(255,255,255,0.08);
    padding-bottom: 10px;
}
.gm-tab-btn {
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-size: 13px;
    font-weight: 600;
    padding: 7px 14px;
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.2s ease, color 0.2s ease;
}
.gm-tab-btn.active {
    background: rgba(212,144,14,0.15);
    color: #fff;
}
.gm-tab-btn:hover:not(.active) {
    background: rgba(255,255,255,0.05);
}
.gm-role-color-opt {
    width: 20px;
    height: 20px;
    border-radius: 7px;
    display: inline-block;
    cursor: pointer;
    border: 2px solid rgba(255,255,255,0.08);
    box-sizing: border-box;
    background: var(--c, #D4900E);
    position: relative;
    box-shadow: inset 0 0 0 1px rgba(0,0,0,0.12), 0 2px 6px rgba(0,0,0,0.18);
}
.gm-role-color-opt:hover {
    border-color: rgba(255,255,255,0.35);
}
.gm-role-color-opt.selected {
    border-color: #fff;
    box-shadow: inset 0 0 0 1px rgba(0,0,0,0.12), 0 0 0 3px var(--c, #D4900E), 0 2px 8px rgba(0,0,0,0.25);
}
.gm-form-label {
    display: block;
    font-size: 10.5px;
    font-weight: 700;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.7px;
    margin-bottom: 9px;
}
.gm-perm-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px;
}
.gm-perm-card {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 8px;
    border-radius: 8px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.03);
    cursor: pointer;
}
.gm-perm-card:has(input:checked) {
    background: rgba(212,144,14,0.12);
    border-color: rgba(212,144,14,0.4);
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.04), 0 2px 10px rgba(212,144,14,0.12);
}
.gm-perm-card-icon {
    flex-shrink: 0;
    width: 18px;
    height: 18px;
    border-radius: 5px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 9px;
}
.gm-perm-card-text {
    flex: 1;
    min-width: 0;
}
.gm-perm-card-title {
