    display: flex;
    gap: 10px;
    align-items: center;
    flex-shrink: 0;
}

/* GF OVERLAY: Mola sohbeti header altından değil, daha aşağıdan başlar */
#group-focus-overlay .cws-break-chat {
    top: 120px;
    right: 0;
    left: auto;
    transform: none !important;
    height: auto;
    max-height: 42vh;
    width: 270px !important;
    bottom: auto !important;
    border-radius: 16px 0 0 16px !important;
    cursor: default;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease !important;
    z-index: 10200;
}
#group-focus-overlay .cws-break-chat.visible {
    opacity: 1 !important;
    pointer-events: all !important;
}
#group-focus-overlay .cws-break-chat.gf-bc-dragging {
    cursor: grabbing !important;
    transition: none !important;
