.dc-profile-menu-item.item-logout  { color: rgba(255,118,117,0.85); }
.dc-profile-menu-item.item-logout:hover { background: rgba(255,71,87,0.12); color: #ff6b6b; }
.dc-profile-menu-item.item-logout .pm-icon { background: rgba(255,71,87,0.15); color: #ff4757; }
