/* ══════════════════════════════════════════════
   GF METRO TİMLİNE
   ══════════════════════════════════════════════ */
.gf-metro-wrapper {
    width: 100%;
    max-width: 900px;
    margin: 18px auto 0;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    overflow: hidden;
}

.gf-metro-track {
    display: flex;
    align-items: center;
    gap: 0;
    overflow-x: auto;
    overflow-y: visible;
    padding: 18px 20px 22px;
    scrollbar-width: none;
    -ms-overflow-style: none;
    width: 100%;
    flex-wrap: nowrap;
}
.gf-metro-track::-webkit-scrollbar { display: none; }

/* ≥5 tur (9+ durak): orta boy */
.gf-metro-track.gf-metro-md .gf-metro-dot { width: 34px; height: 34px; font-size: 13px; }
.gf-metro-track.gf-metro-md .gf-metro-station.active .gf-metro-dot { width: 40px; height: 40px; font-size: 15px; }
.gf-metro-track.gf-metro-md .gf-metro-rail { width: 24px; }
.gf-metro-track.gf-metro-md .gf-metro-label { font-size: 9px; }
.gf-metro-track.gf-metro-md .gf-metro-station.active.focus .gf-metro-label,
.gf-metro-track.gf-metro-md .gf-metro-station.active.brk .gf-metro-label { font-size: 10px; }

/* ≥8 tur (15+ durak): küçük boy */
.gf-metro-track.gf-metro-sm .gf-metro-dot { width: 28px; height: 28px; font-size: 11px; }
.gf-metro-track.gf-metro-sm .gf-metro-station.active .gf-metro-dot { width: 34px; height: 34px; font-size: 13px; }
.gf-metro-track.gf-metro-sm .gf-metro-rail { width: 16px; }
.gf-metro-track.gf-metro-sm .gf-metro-label { font-size: 8px; }
.gf-metro-track.gf-metro-sm .gf-metro-station.active.focus .gf-metro-label,
.gf-metro-track.gf-metro-sm .gf-metro-station.active.brk .gf-metro-label { font-size: 9px; }

/* Durak (station) */
.gf-metro-station {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
    position: relative;
    cursor: default;
}

/* Durak çemberi */
.gf-metro-dot {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    border: 2px solid transparent;
    transition: all 0.4s cubic-bezier(0.34,1.56,0.64,1);
    position: relative;
    z-index: 2;
}

/* Odak durağı */
.gf-metro-station.focus .gf-metro-dot {
    background: rgba(212, 144, 14, 0.15);
    border-color: rgba(212, 144, 14, 0.4);
    color: #D4900E;
}

/* Mola durağı */
.gf-metro-station.brk .gf-metro-dot {
    background: rgba(255, 159, 67, 0.12);
    border-color: rgba(255, 159, 67, 0.35);
    color: #ff9f43;
}

/* Aktif durak */
.gf-metro-station.active .gf-metro-dot {
    width: 48px;
    height: 48px;
    font-size: 18px;
    box-shadow: 0 0 0 6px rgba(46, 213, 115, 0.15);
}
.gf-metro-station.active.focus .gf-metro-dot {
    background: linear-gradient(135deg, #2ed573, #00b894);
    border-color: #2ed573;
    color: #fff;
    box-shadow: 0 0 0 6px rgba(46, 213, 115, 0.18), 0 4px 16px rgba(46, 213, 115, 0.35);
}
.gf-metro-station.active.brk .gf-metro-dot {
    background: linear-gradient(135deg, #ff9f43, #e17055);
    border-color: #ff9f43;
    color: #fff;
    box-shadow: 0 0 0 6px rgba(255, 159, 67, 0.18), 0 4px 16px rgba(255, 159, 67, 0.35);
}

/* Aktif durak nabız animasyonu */
@keyframes gfStationPulse {
    0%, 100% { box-shadow: 0 0 0 6px rgba(46,213,115,0.18), 0 4px 16px rgba(46,213,115,0.35); }
    50%       { box-shadow: 0 0 0 10px rgba(46,213,115,0.08), 0 4px 24px rgba(46,213,115,0.5); }
}
@keyframes gfStationPulseBreak {
    0%, 100% { box-shadow: 0 0 0 6px rgba(255,159,67,0.18), 0 4px 16px rgba(255,159,67,0.35); }
    50%       { box-shadow: 0 0 0 10px rgba(255,159,67,0.08), 0 4px 24px rgba(255,159,67,0.5); }
}
.gf-metro-station.active.focus .gf-metro-dot { animation: gfStationPulse 2s ease-in-out infinite; }
.gf-metro-station.active.brk   .gf-metro-dot { animation: gfStationPulseBreak 2s ease-in-out infinite; }

/* Tamamlanmış durak */
.gf-metro-station.done .gf-metro-dot {
    background: rgba(255,255,255,0.05);
    border-color: rgba(255,255,255,0.12);
    color: rgba(255,255,255,0.25);
}

/* Durak etiketi */
.gf-metro-label {
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.5px;
    text-align: center;
    transition: color 0.3s;
    white-space: nowrap;
}
.gf-metro-station.focus .gf-metro-label { color: rgba(162,155,254,0.7); }
.gf-metro-station.brk   .gf-metro-label { color: rgba(255,159,67,0.7); }
.gf-metro-station.active.focus .gf-metro-label { color: #2ed573; font-size: 11px; }
.gf-metro-station.active.brk   .gf-metro-label { color: #ff9f43; font-size: 11px; }
.gf-metro-station.done  .gf-metro-label { color: rgba(255,255,255,0.18); }

/* Duraklar arası ray */
.gf-metro-rail {
    width: 36px;
    height: 3px;
    flex-shrink: 0;
    border-radius: 2px;
    transition: background 0.4s ease;
    margin-bottom: 28px;
}
.gf-metro-rail.done  { background: rgba(255,255,255,0.22); }
.gf-metro-rail.ahead { background: rgba(255,255,255,0.07); }

/* Ayarlar butonu satırı */
.gf-metro-settings-row {
    display: flex;
    justify-content: center;
}
.gf-metro-settings-btn {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 7px 18px;
    border-radius: 20px;
    border: 1px solid rgba(255,255,255,0.12);
    background: rgba(255,255,255,0.06);
    color: rgba(255,255,255,0.55);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}
.gf-metro-settings-btn:hover {
    background: rgba(212,144,14,0.18);
    border-color: rgba(212,144,14,0.4);
    color: #D4900E;
}

/* ══════════════════════════════════════════════
   OTURUMU BİTİR / YENİDEN BAŞLAT MODALLARI
   ══════════════════════════════════════════════ */
.gf-end-modal-card {
