    border: 1px solid rgba(255,255,255,0.12);
    background: rgba(255,255,255,0.06);
    color: rgba(255,255,255,0.7);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    transition: all 0.2s;
}
.gf-end-btn-cancel:hover { background: rgba(255,255,255,0.1); }
.gf-end-btn-confirm {
    flex: 1;
    padding: 13px 16px;
    border-radius: 12px;
    border: none;
    background: linear-gradient(135deg, #2ed573, #00b894);
    box-shadow: 0 6px 20px rgba(46,213,115,0.4);
    color: #fff;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    transition: all 0.2s;
}
.gf-end-btn-confirm:hover { transform: translateY(-2px); filter: brightness(1.08); }

/* Ayarlar modal restart butonu */
.gf-restart-btn {
    width: 100%;
    padding: 11px 16px;
    border-radius: 12px;
    border: 1px solid rgba(253,203,110,0.3);
    background: rgba(253,203,110,0.08);
    color: #fdcb6e;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    transition: all 0.2s;
}
.gf-restart-btn:hover {
    background: rgba(253,203,110,0.16);
    border-color: rgba(253,203,110,0.5);
}

/* ── Ayarlar Modalı — Oturum Özeti Kartı ── */
.gf-settings-session-info {
    background: rgba(212,144,14,0.07);
    border: 1px solid rgba(212, 144, 14, 0.2);
    border-radius: 14px;
    padding: 14px 16px;
    margin-bottom: 20px;
}

.gf-ssi-chips {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-bottom: 10px;
}
.gf-ssi-chip {
    display: flex;
    align-items: center;
    gap: 6px;
    background: rgba(212,144,14,0.12);
    border: 1px solid rgba(212,144,14,0.25);
    border-radius: 20px;
    padding: 5px 12px;
    font-size: 12px;
    font-weight: 600;
    color: #fff;
}
.gf-ssi-chip i { color: #D4900E; font-size: 11px; }


/* ── Partner Yeniden Başlatıyor Modalı ── */
.gf-restarting-card {
    position: relative;
    overflow: hidden;
}
.gf-restarting-anim {
    position: relative;
    width: 80px;
    height: 80px;
    margin: 0 auto 20px;
    display: flex;
    align-items: center;
    justify-content: center;
}
.gf-restarting-ring {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 2px solid rgba(253, 203, 110, 0.35);
    animation: gfRestartPulse 2s ease-out infinite;
}
.gf-restarting-ring-2 {
    animation-delay: 0.8s;
    border-color: rgba(225, 112, 85, 0.25);
}
@keyframes gfRestartPulse {
    0%   { transform: scale(0.6); opacity: 1; }
    100% { transform: scale(1.5); opacity: 0; }
}
.gf-restarting-icon {
    font-size: 26px;
    background: linear-gradient(135deg, #fdcb6e, #e17055);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: gfRestartSpin 3s linear infinite;
}
@keyframes gfRestartSpin {
    from { transform: rotate(0deg); }
    to   { transform: rotate(-360deg); }
}
.gf-restarting-status {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    font-size: 13px;
    color: var(--text-muted);
    margin-top: 4px;
}
.gf-restarting-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #fdcb6e;
    animation: bcPulse 1.5s infinite;
}

/* ══════════════════════════════════════════════════════════
   GRUP ODAK SEANSİ TAKVİMİ
══════════════════════════════════════════════════════════ */

/* İstatistik kartları */
.gsc-stats-row {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin-bottom: 4px;
}
.gsc-stats-row.cols-4 {
    grid-template-columns: repeat(4, 1fr);
}
.gsc-stat-card {
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 12px;
    padding: 12px 8px;
    text-align: center;
}
.gsc-stat-val {
    font-size: 22px;
    font-weight: 700;
    color: #fff;
    line-height: 1;
}
.gsc-stat-label {
    font-size: 10px;
    color: var(--text-muted);
    margin-top: 4px;
}

/* Haftalık takvim — Tasarım B: sade 7 sütun + alttaki tek gün detay paneli */
.gsc-week-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 6px;
}
.gsc-day-col {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 3px;
    min-width: 0;
    padding: 8px 2px 10px;
    border-radius: 10px;
    border: 1px solid transparent;
    cursor: pointer;
    transition: all 0.15s;
}
.gsc-day-col:hover {
    background: rgba(255,255,255,0.04);
}
.gsc-day-col.selected {
    background: rgba(108,92,231,0.14);
    border-color: rgba(108,92,231,0.45);
}
.gsc-day-name {
    font-size: 10px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.3px;
}
.gsc-day-col.today .gsc-day-name {
    color: #74b9ff;
}
.gsc-day-num {
    font-size: 14px;
    font-weight: 600;
    color: rgba(255,255,255,0.85);
}
.gsc-day-col.today .gsc-day-num {
    color: #74b9ff;
}
.gsc-day-col.selected .gsc-day-num {
    color: #fff;
}
.gsc-day-dots {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 3px;
    min-height: 6px;
}
.gsc-day-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: rgba(212,144,14,0.7);
}
.gsc-day-dot.mine {
    background: #74b9ff;
}
.gsc-day-dot-more {
    font-size: 8px;
    color: var(--text-muted);
    margin-left: 1px;
}
/* "Takvim + ödev tarihleri birleşimi" — teslim tarihi olan günlerde küçük bayrak rozeti */







/* Seçili gün detay paneli */
.gsc-day-detail {
    margin-top: 12px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 12px;
    padding: 12px;
}
.gsc-day-detail-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 12px;
    font-weight: 600;
    color: rgba(255,255,255,0.85);
    margin-bottom: 10px;
}
.gsc-day-detail-empty {
    font-size: 12px;
    color: var(--text-muted);
    text-align: center;
    padding: 14px 4px;
}
.gsc-day-detail-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.gsc-day-detail-row {
    display: flex;
    align-items: center;
    gap: 10px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-left: 2px solid rgba(212,144,14,0.5);
    border-radius: 8px;
    padding: 7px 10px;
    cursor: pointer;
    transition: all 0.15s;
}
.gsc-day-detail-row:hover {
    background: rgba(255,255,255,0.07);
    border-color: rgba(255,255,255,0.14);
    border-left-color: rgba(212,144,14,0.8);
}
.gsc-day-detail-row.completed {
    background: rgba(255,255,255,0.025);
    border-color: rgba(255,255,255,0.06);
    border-left-color: rgba(255,255,255,0.15);
}
.gsc-day-detail-row.completed .gsc-ddr-time { color: var(--text-muted); }
.gsc-day-detail-row.mine {
    border-color: rgba(116,185,255,0.5);
}
.gsc-ddr-time {
    font-size: 11px;
    font-weight: 700;
    color: rgba(255,255,255,0.85);
    flex-shrink: 0;
    width: 76px;
}
.gsc-ddr-main {
    flex: 1;
    min-width: 0;
}
.gsc-ddr-title {
    font-size: 12px;
    color: rgba(255,255,255,0.85);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.gsc-ddr-sub {
    font-size: 10px;
    color: rgba(255,255,255,0.4);
    margin-top: 1px;
}
.gsc-live-dot {
    display: inline-block;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #74b9ff;
    margin-right: 3px;
    animation: gscLivePulse 1.4s ease-in-out infinite;
}
@keyframes gscLivePulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.35; }
}
.gsc-ddr-focus-btn {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 10px;
    font-weight: 700;
    color: #fff;
    background: var(--primary-color);
    border: none;
    border-radius: 20px;
    padding: 6px 11px;
    cursor: pointer;
    transition: opacity 0.15s, transform 0.15s;
}
.gsc-ddr-focus-btn:hover { opacity: 0.85; transform: translateY(-1px); }
.gsc-pill-avatars {
    display: flex;
    justify-content: center;
    margin-top: 3px;
}
.gsc-pill-avatars img,
.gsc-pill-avatars .gsc-pill-avatar-fallback {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    border: 1.5px solid rgba(20,20,25,0.9);
    margin-left: -4px;
    object-fit: cover;
}
.gsc-pill-avatars > *:first-child {
    margin-left: 0;
}
.gsc-pill-avatar-fallback {
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255,255,255,0.12);
    color: rgba(255,255,255,0.7);
    font-size: 7px;
    font-weight: 700;
}

/* Seans detay modal */
.gsc-modal-overlay {
    position: fixed; inset: 0; z-index: 10500;
    background: rgba(0,0,0,0.6);
    backdrop-filter: blur(6px);
    display: flex; align-items: center; justify-content: center;
    animation: fcOverlayIn 0.18s ease;
}
.gsc-modal-box {
    background: linear-gradient(145deg, #16132a, #1e1a35);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 18px;
    padding: 28px;
    width: min(420px, 92vw);
    max-height: 90vh;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 16px;
    box-shadow: 0 24px 60px rgba(0,0,0,0.6), 0 0 0 1px rgba(212,144,14,0.15);
    animation: fcBoxIn 0.22s cubic-bezier(0.34,1.56,0.64,1);
}
.gsc-modal-title {
    font-size: 17px;
    font-weight: 700;
    color: #fff;
    display: flex;
    align-items: center;
    gap: 10px;
}
.gsc-modal-title i { color: #D4900E; }
.gsc-form-row {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.gsc-form-label {
    font-size: 12px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}
.gsc-form-input {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 10px;
    padding: 10px 14px;
    color: #fff;
    font-size: 13px;
    outline: none;
    width: 100%;
    box-sizing: border-box;
    transition: border-color 0.2s;
}
.gsc-form-input:focus { border-color: rgba(212,144,14,0.6); }
.gsc-two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.gsc-modal-footer {
    display: flex;
    gap: 10px;
    justify-content: flex-end;
    padding-top: 4px;
}
.gsc-modal-footer .control-btn.secondary {
    background: rgba(255,255,255,0.07);
    color: rgba(255,255,255,0.7);
    border: 1px solid rgba(255,255,255,0.1);
}
.gsc-modal-footer .control-btn.secondary:hover { background: rgba(255,255,255,0.12); }
.gsc-modal-footer .primary-btn {
    background: linear-gradient(135deg, #D4900E, #D4900E);
    color: #fff;
    box-shadow: 0 6px 20px rgba(212,144,14,0.4);
    border: none;
}

/* Bekleme odası */
.gsc-waiting-chip {
    font-size: 12px; font-weight: 600;
    background: rgba(255,255,255,0.08);
    color: #fff;
    border: 1px solid rgba(255,255,255,0.14);
    padding: 4px 10px; border-radius: 20px;
}
.gsc-waiting-empty {
    font-size: 12px;
    color: var(--text-muted);
}

/* Seans detay görünümü */
.gsc-detail-title {
    font-size: 18px; font-weight: 700; color: #fff; margin: 0;
}
.gsc-detail-meta {
    display: flex; flex-wrap: wrap; gap: 8px; margin-top: 4px;
}
.gsc-detail-badge {
    font-size: 11px; font-weight: 600;
    background: rgba(212,144,14,0.15);
    color: #D4900E;
    border: 1px solid rgba(212,144,14,0.3);
    padding: 3px 10px; border-radius: 20px;
}
.gsc-detail-badge.green {
    background: rgba(255,255,255,0.06);
    color: var(--text-muted);
    border-color: rgba(255,255,255,0.14);
}
.gsc-detail-badge.live {
    background: rgba(116,185,255,0.12);
    color: #74b9ff;
    border-color: rgba(116,185,255,0.3);
}
.gsc-attendee-grid {
    display: flex; flex-wrap: wrap; gap: 8px;
    max-height: 120px; overflow-y: auto;
}
.gsc-attendee-chip {
    display: flex; align-items: center; gap: 6px;
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 20px;
    padding: 4px 10px 4px 4px;
    font-size: 12px; color: rgba(255,255,255,0.8);
}
.gsc-rsvp-btn {
    width: 100%;
    padding: 11px;
    border-radius: 12px;
    border: none;
    font-size: 13px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s;
    display: flex; align-items: center; justify-content: center; gap: 8px;
}
.gsc-rsvp-btn.join {
    background: linear-gradient(135deg, #D4900E, #D4900E);
    color: #fff;
}
.gsc-rsvp-btn.join:hover { opacity: 0.85; transform: translateY(-1px); }
.gsc-rsvp-btn.leave {
    background: rgba(255,71,87,0.15);
    color: #ff4757;
    border: 1px solid rgba(255,71,87,0.3);
}
.gsc-rsvp-btn.leave:hover { background: rgba(255,71,87,0.25); }
.gsc-delete-btn {
    background: none; border: none;
    color: rgba(255,71,87,0.5); font-size: 11px;
    cursor: pointer; padding: 0;
    transition: color 0.2s;
    align-self: flex-start;
}
.gsc-delete-btn:hover { color: #ff4757; }

.gsc-form-input[type="date"],
.gsc-form-input[type="time"] {
    color-scheme: dark;
}

/* ===== GROUPS HUB LAYOUT ===== */
.groups-hub-layout {
    display: flex;
    gap: 0;
    height: calc(100vh - 200px);
    min-height: 420px;
    max-height: 900px;
    border-radius: 16px;
    overflow: hidden;
}

/* SOL SIDEBAR */
.groups-hub-sidebar {
    width: 300px;
    min-width: 280px;
    max-width: 320px;
    display: flex;
    flex-direction: column;
    gap: 0;
    padding: 16px 14px;
    border-radius: 16px 0 0 16px !important;
    border-right: 1px solid rgba(255,255,255,0.06) !important;
    overflow-y: auto;
    overflow-x: hidden;
    flex-shrink: 0;
}

.groups-hub-sidebar::-webkit-scrollbar { width: 4px; }
.groups-hub-sidebar::-webkit-scrollbar-track { background: transparent; }
.groups-hub-sidebar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.08); border-radius: 2px; }

/* AKILLI ARAMA KUTUSU */
.groups-hub-search-box {
    margin-bottom: 10px;
}

.groups-hub-input-row {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 10px;
    padding: 0 12px;
    transition: border-color 0.2s;
}

.groups-hub-input-row:focus-within {
    border-color: rgba(212,144,14,0.5);
}

.groups-hub-input-icon {
    color: var(--text-muted);
    font-size: 13px;
    flex-shrink: 0;
    transition: color 0.2s;
}

.groups-hub-input-row.is-code .groups-hub-input-icon {
    color: #D4900E;
}

.groups-hub-input {
    background: transparent;
    border: none;
    outline: none;
    color: #fff;
    font-size: 13px;
    padding: 10px 0;
    width: 100%;
    font-family: inherit;
}

.groups-hub-input::placeholder {
    color: rgba(255,255,255,0.25);
    font-size: 12px;
}

.groups-hub-join-btn {
    margin-top: 8px;
    width: 100%;
    justify-content: center;
    font-size: 13px;
    padding: 9px;
    background: var(--primary-color) !important;
    border: none !important;
    animation: hub-slide-in 0.2s ease;
}

@keyframes hub-slide-in {
    from { opacity: 0; transform: translateY(-6px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* GRUP OLUŞTUR / KEŞFET */
.groups-hub-action-row {
    display: flex;
    gap: 8px;
    margin-bottom: 16px;
}

.groups-hub-create-btn,
.groups-hub-discover-btn {
    flex: 1;
    justify-content: center;
    font-size: 12.5px;
    padding: 9px;
    background: var(--primary-color) !important;
    border: none !important;
    white-space: nowrap;
}

.groups-hub-discover-btn {
    background: rgba(255,255,255,0.06) !important;
    color: #fff !important;
}

/* GRUBA DAVET MODALI — kod rozeti */
.my-group-card-code-text {
    font-family: monospace;
    font-weight: bold;
    letter-spacing: 0.05em;
    background: rgba(212, 144, 14, 0.15);
    color: #D4900E;
    padding: 3px 8px;
    border-radius: 5px;
    border: 1px solid rgba(212, 144, 14, 0.2);
    font-size: 13px;
}

/* BÖLÜM BAŞLIKLARI */
.groups-hub-section {
    margin-bottom: 8px;
    padding-top: 14px;
    border-top: 1px solid rgba(255,255,255,0.05);
}

.groups-hub-section:first-of-type {
    padding-top: 0;
    border-top: none;
}

.groups-hub-section-title {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(255,255,255,0.35);
    padding: 0 4px 10px 4px;
    display: flex;
    align-items: center;
    gap: 6px;
}

/* GRUP KARTI (sidebar içinde) */
.my-group-card-item {
    padding: 8px !important;
    border-radius: 10px !important;
    cursor: pointer;
    background: rgba(255,255,255,0.02) !important;
    border: 1px solid rgba(255,255,255,0.04) !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
    margin-bottom: 5px !important;
    overflow: hidden;
}

.my-group-card-item:hover {
    background: rgba(255,255,255,0.05) !important;
    border-color: rgba(212,144,14,0.3) !important;
}

.my-group-card-item.active-hub-group {
    background: rgba(212,144,14,0.12) !important;
    border-color: var(--primary-color) !important;
}

/* GRUP AVATARI — kod'a göre renklenen, baş harfli rozet */
.group-avatar {
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-weight: 700;
    flex-shrink: 0;
    box-shadow: 0 4px 10px rgba(0,0,0,0.2);
}

/* GRUPLARIM KART İÇERİĞİ */
.my-group-card-row {
    display: flex;
    align-items: center;
    gap: 10px;
}

.my-group-card-body {
    flex: 1;
    min-width: 0;
}

.my-group-card-name {
    margin: 0;
    font-size: 12.5px;
    font-weight: 600;
    color: #fff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.my-group-card-meta {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 3px;
    font-size: 10.5px;
    color: var(--text-muted);
}

.my-group-card-members {
    display: flex;
    align-items: center;
    gap: 4px;
}

.my-group-card-active-mini {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    color: #2ed573;
}
.my-group-card-active-mini i { font-size: 6px; }

/* SAĞ DETAY PANELİ */
.groups-hub-panel {
    flex: 1;
    border-radius: 0 16px 16px 0 !important;
    overflow-y: auto;
    padding: 25px !important;
    display: flex;
    flex-direction: column;
    gap: 20px;
}

