/* ── Kurumsal grup TANITIM kartı (Genel Bakış — sınıf/ekip grupları) ──
   Analitik değil, "bu grup ne, kim yönetiyor, kaç kişi var" sorularına cevap veren
   vitrin kartı. Analitik veriler (KPI/risk/yoğunluk) Sınıf Paneli'nin Özet sekmesindedir. */
.grp-intro-card {
    padding: 18px 20px; border-radius: 16px;
    background: linear-gradient(135deg, rgba(108,92,231,0.08), rgba(108,92,231,0.02));
    border: 1px solid rgba(108,92,231,0.18);
}

.grp-intro-code i.fa-copy {
    font-size: 12px; font-weight: 400; color: var(--text-muted); cursor: pointer; transition: color .15s;
}
.grp-intro-code i.fa-copy:hover { color: #a29bfe; }
.grp-intro-cta-btn { display: inline-flex; align-items: center; gap: 8px; font-size: 12.5px; }

/* ── Premium istatistik kartları (üye/şube sayısı) — sadeleştirilmiş Genel Bakış
   (2026-07-12, kullanıcı geri bildirimi: eski hâli avatar yığını + rakamların iç içe
   geçtiği karmaşık bir satırdı). Her kart kendi rengiyle net bir şekilde ayrışır. ── */
.grp-stat-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 12px; margin-bottom: 16px; }
.grp-stat-tile {
    display: flex; align-items: center; gap: 12px; padding: 14px 16px; border-radius: 14px;
    background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.07);
    transition: transform .15s, border-color .15s;
}
.grp-stat-tile:hover { transform: translateY(-2px); border-color: rgba(108,92,231,0.3); }
.grp-stat-tile-icon {
    width: 40px; height: 40px; border-radius: 12px; flex-shrink: 0;
    display: flex; align-items: center; justify-content: center; font-size: 16px;
}
.grp-stat-tile-icon--purple { background: rgba(108,92,231,0.14); color: #a29bfe; }
.grp-stat-tile-icon--teal { background: rgba(78,205,196,0.14); color: #4ecdc4; }
.grp-stat-tile-num { font-size: 22px; font-weight: 800; color: #fff; line-height: 1.15; }
.grp-stat-tile-label { font-size: 11px; font-weight: 600; color: var(--text-muted); }

.grp-intro-shortcuts-toggle {
    display: flex; align-items: center; gap: 8px; width: 100%;
    padding: 10px 12px; border-radius: 10px; cursor: pointer; text-align: left;
    background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.07);
    color: #e0e0e0; font-size: 12.5px; font-weight: 600;
    transition: background .15s, border-color .15s;
}
.grp-intro-shortcuts-toggle i:first-child { color: var(--text-muted); font-size: 12px; }
.grp-intro-shortcuts-toggle:hover { background: rgba(108,92,231,0.1); border-color: rgba(108,92,231,0.3); }
.grp-intro-shortcuts-collapse { margin-top: 10px; }

.grp-intro-shortcuts {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(90px, 1fr)); gap: 8px;
    min-height: 76px;
}
.grp-intro-shortcut-btn {
    position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px;
    padding: 12px 8px; border-radius: 12px; cursor: pointer; text-align: center;
    background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.07);
    color: #e0e0e0; font-size: 11.5px; font-weight: 600;
    transition: background .15s, border-color .15s, transform .1s;
}
.grp-intro-shortcut-btn i {
    font-size: 15px; color: var(--primary-color);
}
.grp-intro-shortcut-btn:hover {
    background: rgba(108,92,231,0.12); border-color: rgba(108,92,231,0.35);
}
.grp-intro-shortcut-btn:active { transform: scale(0.97); }
.grp-intro-shortcut-btn[data-shortcut="asg-add"] {
    background: rgba(108,92,231,0.1); border-color: rgba(108,92,231,0.25);
}
.grp-intro-shortcut-btn.is-dragging { opacity: 0.4; }
.grp-intro-shortcut-btn.is-drag-over { border-color: var(--primary-color); background: rgba(108,92,231,0.18); }
.grp-intro-shortcut-btn.is-ghost {
    border-style: dashed; border-color: rgba(108,92,231,0.5); background: rgba(108,92,231,0.1);
    animation: grpShortcutGhostIn .12s ease;
}
@keyframes grpShortcutGhostIn {
    from { transform: scale(0.85); opacity: 0.4; }
    to { transform: scale(1); opacity: 1; }
}
.grp-intro-shortcut-handle {
    position: absolute; top: 5px; right: 6px; font-size: 9px !important; color: var(--text-muted) !important;
    opacity: 0; cursor: grab; transition: opacity .15s;
}
.grp-intro-shortcut-btn:hover .grp-intro-shortcut-handle { opacity: 0.6; }
.grp-intro-shortcut-edit {
    background: rgba(255,255,255,0.015); border-style: dashed; color: var(--text-muted);
}
.grp-intro-shortcut-edit i { color: var(--text-muted); }
.grp-intro-shortcut-edit:hover { color: #e0e0e0; border-color: rgba(255,255,255,0.2); }

.grp-shortcut-gallery {
    margin-top: 10px; padding: 12px; border-radius: 12px;
    background: rgba(20,18,30,0.6); border: 1px solid rgba(108,92,231,0.25);
    box-shadow: 0 8px 24px rgba(0,0,0,0.35);
    animation: grpShortcutGalleryIn .15s ease;
}
@keyframes grpShortcutGalleryIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}
.grp-shortcut-gallery-hint {
    font-size: 11px; color: var(--text-muted); margin-bottom: 10px; display: flex; align-items: center; gap: 6px;
}
.grp-shortcut-gallery-list {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 8px;
}
.grp-shortcut-gallery-item {
    display: flex; align-items: center; gap: 8px; padding: 9px 10px; border-radius: 10px;
    background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.07);
    font-size: 12px; font-weight: 600; color: #e0e0e0; cursor: grab;
    transition: background .15s, border-color .15s;
}
.grp-shortcut-gallery-item i:first-child { color: var(--primary-color); font-size: 13px; }
.grp-shortcut-gallery-toggle { margin-left: auto; font-size: 10px !important; color: var(--text-muted) !important; }
.grp-shortcut-gallery-item.is-added {
    background: rgba(108,92,231,0.14); border-color: rgba(108,92,231,0.35);
}
.grp-shortcut-gallery-item.is-added .grp-shortcut-gallery-toggle { color: #a29bfe !important; }
.grp-shortcut-gallery-item:hover { border-color: rgba(108,92,231,0.4); }

