}
/* Toggle switch */
.ss-toggle {
    position: relative;
    display: inline-block;
    width: 40px;
    height: 22px;
    flex-shrink: 0;
    cursor: pointer;
}
.ss-toggle input { opacity: 0; width: 0; height: 0; }
.ss-slider {
    position: absolute;
    inset: 0;
    background: rgba(255,255,255,0.12);
    border-radius: 22px;
    transition: background 0.2s;
}
.ss-slider::before {
    content: '';
    position: absolute;
    width: 16px;
    height: 16px;
    left: 3px;
    top: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
}
.ss-toggle input:checked + .ss-slider { background: var(--primary-color); }
.ss-toggle input:checked + .ss-slider::before { transform: translateX(18px); }
/* Data action row */
.ss-action-btn {
