}
.td-chip-done .td-chip-val { color: #4ADE80; }
.td-chip-streak { flex: 0 0 auto; }
.td-chip-streak .td-chip-val { color: var(--a); }

/* ── BEKLEYEN CHİP DİKKAT ÇEKMEsi ── */
@keyframes chip-pending-pulse {
    0%   { box-shadow: 0 0 0 0   rgba(255,159,67,0.55), 0 0  0px 0px rgba(255,159,67,0); }
    40%  { box-shadow: 0 0 0 5px rgba(255,159,67,0.18), 0 0 14px 2px rgba(255,159,67,0.12); }
    100% { box-shadow: 0 0 0 0   rgba(255,159,67,0),    0 0  0px 0px rgba(255,159,67,0); }
}
@keyframes chip-pending-border {
    0%, 100% { border-color: rgba(255,159,67,0.18); }
    40%       { border-color: rgba(255,159,67,0.55); }
}
.td-chip-pending-active {
    animation:
        chip-pending-pulse  2.8s ease-in-out infinite,
        chip-pending-border 2.8s ease-in-out infinite;
}

/* ── SAYI ROLL ANIMASYONU ── */
@keyframes chip-roll-up {
    0%   { opacity: 0; transform: translateY(10px) scale(0.85); filter: blur(2px); }
    60%  { opacity: 1; transform: translateY(-2px) scale(1.04); filter: blur(0); }
    100% { opacity: 1; transform: translateY(0)   scale(1);    filter: blur(0); }
}
@keyframes chip-roll-down {
    0%   { opacity: 0; transform: translateY(-10px) scale(0.85); filter: blur(2px); }
    60%  { opacity: 1; transform: translateY(2px)   scale(1.04); filter: blur(0); }
    100% { opacity: 1; transform: translateY(0)     scale(1);    filter: blur(0); }
}
.td-chip-val {
    display: inline-block; /* transform çalışsın */
    will-change: transform, opacity;
}
.td-chip-val.rolling {
    animation-duration: 380ms;
    animation-timing-function: cubic-bezier(0.34, 1.56, 0.64, 1);
    animation-fill-mode: both;
}
.td-chip-val.roll-up   { animation-name: chip-roll-up; }
.td-chip-val.roll-down { animation-name: chip-roll-down; }

/* ── TAMAMLANAN CHİP KUTLAMA — PREMİUM ── */

/* 1. Chip'in kendisi: çarpıp geri gelsin, yeşil parlasın */
@keyframes chip-done-celebrate {
    0%   { transform: scale(1);    box-shadow: 0 0 0 0 rgba(74,222,128,0.7),  0 0 0px  0px rgba(74,222,128,0); }
    18%  { transform: scale(1.12); box-shadow: 0 0 0 6px rgba(74,222,128,0.35), 0 0 18px 4px rgba(74,222,128,0.25); }
    36%  { transform: scale(0.94); box-shadow: 0 0 0 10px rgba(74,222,128,0.1), 0 0 28px 6px rgba(74,222,128,0.15); }
    54%  { transform: scale(1.04); box-shadow: 0 0 0 14px rgba(74,222,128,0),   0 0 36px 8px rgba(74,222,128,0.08); }
    72%  { transform: scale(0.98); }
    100% { transform: scale(1);    box-shadow: 0 0 0 0 rgba(74,222,128,0),     0 0 0px  0px rgba(74,222,128,0); }
}
.td-chip-done.celebrate {
    animation: chip-done-celebrate 650ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
    position: relative;
}

/* 2. Border flash: ani yeşil border → solar */
@keyframes chip-border-flash {
    0%   { border-color: rgba(74,222,128,0.9); }
    60%  { border-color: rgba(74,222,128,0.3); }
    100% { border-color: rgba(74,222,128,0.15); }
}
.td-chip-done.celebrate {
    animation: chip-done-celebrate 650ms cubic-bezier(0.34, 1.56, 0.64, 1) both,
               chip-border-flash  650ms ease-out both;
}

/* 3. Sayı: scale punch ayrıca */
.td-chip-done.celebrate .td-chip-val {
    animation: chip-val-punch 500ms cubic-bezier(0.34, 1.56, 0.64, 1) both 40ms;
}
@keyframes chip-val-punch {
    0%   { transform: scale(1);    color: #4ADE80; text-shadow: none; }
    30%  { transform: scale(1.35); color: #86EFAC; text-shadow: 0 0 12px rgba(74,222,128,0.8); }
    65%  { transform: scale(0.9);  color: #4ADE80; text-shadow: 0 0 4px rgba(74,222,128,0.3); }
    100% { transform: scale(1);    color: #4ADE80; text-shadow: none; }
}

/* 4. Parçacıklar — JS tarafından oluşturulan .chip-particle elementleri */
.chip-particle {
    position: fixed;
    width: 5px;
    height: 5px;
    border-radius: 50%;
    pointer-events: none;
    z-index: 9999;
    animation: chip-particle-fly var(--dur, 700ms) cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}
@keyframes chip-particle-fly {
    0%   { transform: translate(0, 0) scale(1);   opacity: 1; }
    70%  { opacity: 0.7; }
    100% { transform: translate(var(--tx), var(--ty)) scale(0); opacity: 0; }
}

