/* ================================================================
   ANA HEDEFLER — Sade & Minimalist Yeniden Tasarım
   ================================================================ */

/* --- Tab Bar --- */
.goal-tabs-minimal {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    padding-bottom: 0;
}
.goal-tabs-minimal-left { display: flex; gap: 0; }
.goal-tab-min {
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 13px;
    font-weight: 500;
    padding: 8px 16px;
    cursor: pointer;
    border-bottom: 2px solid transparent;
    margin-bottom: -1px;
    transition: color 0.2s, border-color 0.2s;
    font-family: inherit;
}
.goal-tab-min:hover { color: #fff; }
.goal-tab-min.active {
    color: var(--primary-color);
    border-bottom-color: var(--primary-color);
    font-weight: 600;
}
.goal-sort-min {
    background: none;
    border: none;
    color: var(--text-muted);
    font-size: 12px;
    outline: none;
    cursor: pointer;
    font-family: inherit;
    padding: 4px 0;
}
.goal-sort-min option { background: #1e1b4b; color: #fff; }

/* --- Goal Card --- */
.goal-card {
    position: relative;
    padding: 16px 19px !important;
    border-radius: 10px !important;
    background: rgba(255,255,255,0.025) !important;
    border: 1px solid rgba(255,255,255,0.07) !important;
    border-left: 3px solid var(--primary-color) !important;
    transition: background 0.15s !important;
    transform: none !important;
    box-shadow: none !important;
    cursor: pointer;
    margin-bottom: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 10px !important;
    flex-shrink: 0 !important;
}
.goal-card:hover {
    background: rgba(255,255,255,0.04) !important;
    border-color: rgba(255,255,255,0.1) !important;
    border-left-color: var(--primary-color) !important;
    transform: none !important;
    box-shadow: none !important;
}

/* Top row */
.gc-top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 12px;
}
.gc-left { flex: 1; min-width: 0; }
.gc-right {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
}
.gc-title {
    font-size: 15px;
    font-weight: 600;
    color: #fff;
    line-height: 1.3;
    margin-bottom: 5px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}


/* Badge */
.gc-badge {
    font-size: 11px;
    font-weight: 600;
    padding: 3px 9px;
    border-radius: 20px;
    border: 1px solid;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    white-space: nowrap;
    line-height: 1.4;
}
.gc-badge.urgency-safe    { background: rgba(46,213,115,0.08);  color: #2ed573; border-color: rgba(46,213,115,0.18); }
.gc-badge.urgency-warning { background: rgba(255,159,67,0.08);  color: #ff9f43; border-color: rgba(255,159,67,0.18); }
.gc-badge.urgency-danger  { background: rgba(255,71,87,0.08);   color: #ff4757; border-color: rgba(255,71,87,0.18); }
.gc-badge.urgency-none    { background: rgba(255,255,255,0.04); color: var(--text-muted); border-color: rgba(255,255,255,0.08); }

/* Delete btn */
.gc-del-btn {
    background: none;
    border: none;
    color: rgba(255,255,255,0.15);
    cursor: pointer;
    font-size: 11px;
    padding: 3px 4px;
    transition: color 0.15s;
    display: flex;
    align-items: center;
    line-height: 1;
}
.gc-del-btn:hover { color: #ff4757; }

/* Meta satırı: tarih + ödül, tek satır, kutu yok */
.gc-meta-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    row-gap: 4px;
}
.gc-meta-item {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 12px;
    color: var(--text-muted);
    font-weight: 500;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.gc-meta-item i { opacity: 0.55; font-size: 10.5px; flex-shrink: 0; }
.gc-meta-arrow { opacity: 0.35 !important; font-size: 8px !important; margin: 0 1px; }
.gc-meta-reward { color: #feca57; }
.gc-meta-reward i { opacity: 0.8; color: #feca57; }

/* Bağlantı satırı: dönüm noktası / görev / alışkanlık zincirleri */
.gc-link-row {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
}
.gc-stat-chip,
.gc-habit-chip {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 11px;
    font-weight: 600;
    padding: 4px 9px;
    border-radius: 20px;
    line-height: 1.3;
    white-space: nowrap;
    max-width: 160px;
    overflow: hidden;
    text-overflow: ellipsis;
}
.gc-stat-chip {
    background: rgba(108,92,231,0.1);
    color: #a29bfe;
    border: 1px solid rgba(108,92,231,0.22);
}
.gc-stat-chip i { opacity: 0.85; font-size: 10px; }
.gc-habit-chip {
    background: rgba(46,213,115,0.08);
    color: #6fe3a0;
    border: 1px solid rgba(46,213,115,0.2);
}
.gc-habit-chip i { opacity: 0.85; font-size: 10px; }
.gc-habit-chip.gc-habit-more {
    background: rgba(255,255,255,0.04);
    color: var(--text-muted);
    border-color: rgba(255,255,255,0.1);
    font-weight: 500;
}

/* Progress */
.gc-progress-area { display: flex; flex-direction: column; gap: 5px; }
.gc-progress-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 11.5px;
    color: var(--text-muted);
}
.gc-pct { font-weight: 600; color: rgba(255,255,255,0.75); }
.gc-progress-track {
    height: 5px;
    background: rgba(255,255,255,0.07);
    border-radius: 5px;
    overflow: hidden;
}
.gc-progress-fill {
    height: 100%;
    border-radius: 5px;
    transition: width 0.8s ease;
}

/* Action row */
.gc-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 1px;
}
.gc-complete-btn {
    background: none;
    border: 1px solid rgba(46,213,115,0.2);
    color: rgba(46,213,115,0.8);
    font-size: 12px;
    font-weight: 500;
    padding: 4px 12px;
    border-radius: 20px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    transition: background 0.15s, color 0.15s;
    font-family: inherit;
    line-height: 1;
}
.gc-complete-btn:hover { background: rgba(46,213,115,0.1); color: #2ed573; }
.gc-detail-btn {
    background: none;
    border: none;
    font-family: inherit;
    font-size: 12px;
    color: rgba(255,255,255,0.28);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    transition: color 0.15s;
    padding: 0;
}
.gc-detail-btn:hover,
.goal-card:hover .gc-detail-btn { color: var(--primary-color); }

