#zamanlayici .timer-modes {
    display: flex !important;
    gap: 2px !important;
    margin-bottom: 28px !important;
    background: rgba(255,255,255,0.04) !important;
    border: 1px solid rgba(255,255,255,0.07) !important;
    padding: 4px !important;
    border-radius: 10px !important;
    align-items: center;
}
#zamanlayici .mode-btn {
    background: transparent !important;
    border: none !important;
    color: var(--text-muted) !important;
    padding: 7px 16px !important;
    border-radius: 7px !important;
    font-size: 13px !important;
    font-weight: 500 !important;
    cursor: pointer !important;
    transition: background 0.15s, color 0.15s !important;
    font-family: inherit !important;
    box-shadow: none !important;
}
#zamanlayici .mode-btn:hover { color: #fff !important; background: rgba(255,255,255,0.06) !important; }
#zamanlayici .mode-btn.active {
    background: var(--primary-color) !important;
    color: #fff !important;
    box-shadow: none !important;
}
.timer-gear-btn {
    background: none;
    border: none;
    color: rgba(255,255,255,0.25);
    font-size: 14px;
    cursor: pointer;
    padding: 7px 10px;
    border-radius: 7px;
    transition: color 0.15s, background 0.15s;
    display: flex;
    align-items: center;
    margin-left: 2px;
}
.timer-gear-btn:hover { color: var(--primary-color); background: rgba(255,255,255,0.06); }

/* ── Timer çemberi ── */
#zamanlayici .timer-display-wrapper { margin-bottom: 20px !important; }

#zamanlayici .timer-circle {
    width: 240px !important;
    height: 240px !important;
    font-size: 58px !important;
    box-shadow: none !important;
    border: none !important;
    background: transparent !important;
}

#zamanlayici .timer-svg {
    position: absolute;
    top: 0; left: 0;
}

#zamanlayici .timer-ring-bg {
    fill: none;
    stroke: rgba(255,255,255,0.06);
    stroke-width: 3;
}
#zamanlayici .timer-ring-progress {
    fill: none;
    stroke: var(--primary-color);
    stroke-width: 3;
    stroke-linecap: round;
    stroke-dasharray: 691.15;
    stroke-dashoffset: 0;
    transform: rotate(-90deg);
    transform-origin: 50% 50%;
    transition: stroke-dashoffset 1s linear;
    filter: none !important;
}
#zamanlayici .timer-circle.running .timer-ring-progress { filter: none !important; }

/* Moda göre çember rengi: odaklanma mor, kısa mola yeşil, uzun mola turuncu */
#zamanlayici .timer-circle.timer-mode-focus .timer-ring-progress { stroke: #a29bfe !important; }
#zamanlayici .timer-circle.timer-mode-short .timer-ring-progress { stroke: #2ed573 !important; }
#zamanlayici .timer-circle.timer-mode-long  .timer-ring-progress { stroke: #ff9f43 !important; }

#zamanlayici .timer-text {
    color: #fff;
    font-size: 58px;
    font-weight: 700;
    letter-spacing: -1px;
    font-variant-numeric: tabular-nums;
}

/* ── Kontroller ── */
