/* Sabit çıkış butonu (her zaman sağ üstte) */
.focus-exit-btn {
    position: fixed;
    top: 20px;
    right: 24px;
    z-index: 99999;
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(255,255,255,0.15);
    color: rgba(255,255,255,0.7);
    font-size: 13px;
    font-weight: 600;
    padding: 8px 16px;
    border-radius: 20px;
    cursor: pointer;
    font-family: inherit;
    display: none;
    align-items: center;
    gap: 6px;
    transition: background 0.15s, color 0.15s;
    backdrop-filter: blur(8px);
}
.focus-exit-btn:hover { background: rgba(255,255,255,0.15); color: #fff; }

body.focus-mode-active .focus-exit-btn {
    display: flex !important;
