}
.cdd-tasks-badges {
    display: flex;
    align-items: center;
    gap: 6px;
}
.cdd-badge-done {
    font-size: 10px;
    font-weight: 600;
    color: var(--text-muted, #888);
    background: rgba(255,255,255,0.05);
    padding: 2px 7px;
    border-radius: 20px;
    border: 1px solid rgba(255,255,255,0.07);
}
.cdd-badge-time {
    font-size: 10px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 3px;
}
.cdd-task-prog-track {
    height: 3px;
    background: rgba(255,255,255,0.07);
    border-radius: 2px;
    overflow: hidden;
}
.cdd-task-prog-fill {
    height: 100%;
    border-radius: 2px;
    transition: width 0.4s ease;
}

/* Odak hedefi */
.cdd-highlight {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255,159,67,0.1);
    border: 1px solid rgba(255,159,67,0.2);
    border-radius: 8px;
    padding: 8px 10px;
    font-size: 12px;
    color: #fff;
    font-weight: 500;
    cursor: default;
}
.cdd-highlight i.fa-star { color: #ff9f43; flex-shrink: 0; }
.cdd-highlight.completed { opacity: 0.5; text-decoration: line-through; }

/* Görev kartları */
.cdd-event {
    display: flex;
    align-items: center;
    gap: 0;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    border-left: 3px solid #D4900E;
    border-radius: 8px;
    overflow: hidden;
    transition: background 0.15s;
}
.cdd-event:hover { background: rgba(255,255,255,0.07); }
.cdd-event.completed { opacity: 0.5; }

/* Sol tıklanabilir alan */
.cdd-ev-left {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 8px 8px 10px;
    flex: 1;
    min-width: 0;
    cursor: pointer;
}
/* Checkbox circle */
.cdd-ev-check {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 1.5px solid rgba(255,255,255,0.2);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 8px;
    color: #fff;
    flex-shrink: 0;
    transition: all 0.15s;
}
.cdd-ev-check.done {
    background: #2ed573;
    border-color: #2ed573;
}
.cdd-ev-body {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}
.cdd-ev-title {
    font-size: 12px;
    font-weight: 500;
    color: #fff;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.cdd-event.completed .cdd-ev-title { text-decoration: line-through; }
.cdd-ev-time {
    font-size: 10px;
    color: var(--text-muted, #888);
    white-space: nowrap;
}

/* Drag handle */
.cdd-drag-handle {
    display: flex;
    align-items: center;
    padding: 0 6px 0 8px;
    color: rgba(255,255,255,0.18);
    font-size: 10px;
    cursor: grab;
    flex-shrink: 0;
    transition: color 0.15s;
}
.cdd-event:hover .cdd-drag-handle { color: rgba(255,255,255,0.45); }
.cdd-drag-handle:active { cursor: grabbing; }

/* Sürüklenen kart */
.cdd-event.cdd-dragging {
    opacity: 0.45;
    transform: scale(0.98);
    box-shadow: 0 6px 20px rgba(0,0,0,0.4);
}

/* Bırakma hedefi — üst/alt çizgi göstergesi */
.cdd-event.cdd-drag-above {
    border-top: 2px solid #D4900E !important;
    margin-top: -2px;
}
.cdd-event.cdd-drag-below {
    border-bottom: 2px solid #D4900E !important;
    margin-bottom: -2px;
}

/* Sil / Düzenle butonları */
.cdd-ev-actions {
    display: flex;
    flex-direction: column;
    align-self: stretch;
    border-left: 1px solid rgba(255,255,255,0.05);
    flex-shrink: 0;
}
.cdd-act-btn {
    flex: 1;
    background: transparent;
    border: none;
    color: var(--text-muted, #666);
    padding: 0 9px;
    cursor: pointer;
    font-size: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.15s;
    border-bottom: 1px solid rgba(255,255,255,0.04);
}
.cdd-act-btn:last-child { border-bottom: none; }
.cdd-act-btn:hover { background: rgba(255,255,255,0.08); color: #fff; }
.cdd-act-btn.del:hover { background: rgba(255,71,87,0.15); color: #ff4757; }

/* ── Alışkanlık kartı (yeni tasarım) ── */
.cdd-habit-card {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 10px 8px 8px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.06);
    border-radius: 10px;
    transition: background 0.15s, border-color 0.15s;
}
.cdd-habit-card:not(.future):hover {
    background: rgba(255,255,255,0.06);
    border-color: rgba(162,155,254,0.2);
}
.cdd-habit-card.done {
    background: rgba(46,213,115,0.05);
    border-color: rgba(46,213,115,0.15);
}
.cdd-habit-card.future { opacity: 0.5; }

/* Tamamlama butonu */
.cdd-habit-check-btn {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    border: 1.5px solid rgba(255,255,255,0.2);
    background: transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    flex-shrink: 0;
    font-size: 9px;
    color: #fff;
    transition: all 0.2s cubic-bezier(0.34,1.56,0.64,1);
}
.cdd-habit-check-btn:not([disabled]):hover {
    border-color: #2ed573;
    background: rgba(46,213,115,0.1);
    transform: scale(1.12);
}
.cdd-habit-check-btn.done {
    background: #2ed573;
    border-color: #2ed573;
}
.cdd-habit-check-btn:disabled { cursor: default; opacity: 0.4; }

/* Ana içerik */
.cdd-habit-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.cdd-habit-name {
    font-size: 12px;
    font-weight: 500;
    color: #fff;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.cdd-habit-card.done .cdd-habit-name {
    text-decoration: line-through;
    opacity: 0.65;
}

/* 7 günlük mini nokta geçmişi */
.cdd-habit-dots-row {
    display: flex;
    gap: 3px;
    align-items: center;
}
.cdd-hdot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: rgba(255,255,255,0.1);
    flex-shrink: 0;
    transition: background 0.15s;
}
.cdd-hdot.filled { background: #a29bfe; }
.cdd-hdot.today.filled { background: #2ed573; box-shadow: 0 0 4px rgba(46,213,115,0.6); }
.cdd-hdot.today:not(.filled) {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.2);
    width: 7px;
    height: 7px;
}

/* Streak sayacı */
.cdd-habit-streak {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1px;
    flex-shrink: 0;
    min-width: 28px;
}
.cdd-habit-streak i { font-size: 12px; }
.cdd-habit-streak span {
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
}

/* ── Günlük Özet Kartı ── */
.cdd-summary-strip {
    padding: 8px 12px;
    border-bottom: 1px solid rgba(255,255,255,0.05);
    background: rgba(255,255,255,0.02);
    min-width: 300px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

/* Üst satır: durum + not butonu */
.cdd-sum-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
}
.cdd-sum-status {
    display: flex;
    align-items: center;
    gap: 6px;
}
.cdd-sum-icon { font-size: 15px; line-height: 1; }
.cdd-sum-label {
    font-size: 12px;
    font-weight: 700;
}

/* Not butonu */
.cdd-sum-note-btn {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 6px;
    color: var(--text-muted, #666);
    width: 26px;
    height: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 11px;
    transition: all 0.15s;
    flex-shrink: 0;
}
.cdd-sum-note-btn:hover { color: #fff; border-color: rgba(255,255,255,0.2); }
.cdd-sum-note-btn.has-note {
    color: #fdcb6e;
    border-color: rgba(253,203,110,0.3);
    background: rgba(253,203,110,0.07);
}

/* Pill'ler */
.cdd-sum-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
}
.cdd-sum-pill {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 10px;
    font-weight: 500;
    color: var(--text-muted, #888);
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 20px;
    padding: 2px 8px;
    white-space: nowrap;
}
.cdd-sum-pill i { font-size: 9px; opacity: 0.7; }

/* Gün paneli ödev listesi — Bugün'deki "Ana Hedef" task-item kartıyla aynı görsel
   dil (bkz. renderTasks() hlLi, script.js), sadece renk kodlaması farklı.
   .task-item taban kuralı border-left/background'u !important ile sabitlediği
   için (style.css ~22186), burada aynı özgüllükte !important ile eziyoruz. */
.cdd-sum-assignments {
    list-style: none; display: flex; flex-direction: column; gap: 6px; margin: 8px 0 0; padding: 0;
}
.cdd-sum-assignment-item:hover { filter: brightness(1.08); }
.cdd-sum-assignment-item[data-status="pending"] {
    border-left-color: #a29bfe !important;
    background: linear-gradient(90deg, rgba(162,155,254,0.07) 0%, transparent 100%) !important;
}
.cdd-sum-assignment-item[data-status="overdue"] {
    border-left-color: #ff6b6b !important;
    background: linear-gradient(90deg, rgba(255,107,107,0.07) 0%, transparent 100%) !important;
}
.cdd-sum-assignment-item[data-status="done"] {
    border-left-color: #2ed573 !important;
    background: linear-gradient(90deg, rgba(46,213,115,0.07) 0%, transparent 100%) !important;
}

/* Not alanı */
.cdd-sum-note-area {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-top: 2px;
}
.cdd-note-input {
    width: 100%;
    min-height: 60px;
    max-height: 100px;
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    color: #fff;
    font-size: 12px;
    padding: 8px 10px;
    font-family: 'Inter', sans-serif;
    resize: vertical;
    outline: none;
    transition: border-color 0.2s;
    box-sizing: border-box;
}
.cdd-note-input:focus { border-color: rgba(253,203,110,0.4); }
.cdd-note-input::placeholder { color: rgba(255,255,255,0.2); }
.cdd-note-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
}
.cdd-note-chars {
    font-size: 10px;
    color: var(--text-muted, #666);
}
.cdd-note-save {
    background: #D4900E;
    border: none;
    border-radius: 6px;
    color: #fff;
    font-size: 11px;
    font-weight: 600;
    padding: 5px 12px;
    cursor: pointer;
    font-family: 'Inter', sans-serif;
    transition: background 0.15s;
}
.cdd-note-save:hover { background: #b87a0c; }

/* Readonly badge — geçmiş gün bilgilendirmesi */
.cdd-readonly-badge {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 0 12px 0;
    padding: 6px 12px;
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.07);
    border-radius: 8px;
    font-size: 11px;
    font-weight: 500;
    color: var(--text-muted, #888);
}
.cdd-readonly-badge i { font-size: 10px; opacity: 0.7; }

/* Geçmiş gün görev kartı — soluk, sadece toggle aktif */
.cdd-event.readonly {
    opacity: 0.8;
}
.cdd-event.readonly .cdd-ev-left {
    cursor: pointer;
}

/* Boş durum */
.cdd-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 32px 16px;
    color: var(--text-muted, #666);
}
.cdd-empty-icon { font-size: 28px; opacity: 0.4; }
.cdd-empty-text { font-size: 12px; text-align: center; line-height: 1.5; }

/* Günlük görünümde aç butonu */
.cdd-open-daily {
    margin: 0 12px 12px;
    padding: 9px;
    background: transparent;
    border: 1px solid rgba(212,144,14,0.25);
    border-radius: 8px;
    color: #D4900E;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    transition: all 0.15s;
    flex-shrink: 0;
    min-width: 240px;
    font-family: 'Inter', sans-serif;
}
.cdd-open-daily:hover { background: rgba(212,144,14,0.1); border-color: rgba(212,144,14,0.5); color: #fff; }

/* ===== HAFTALIK GÖRÜNÜM TAM YÜKSEKLIK ===== */
.cal-fullpage-section #cal-view-weekly.active {
    flex: 1 !important;
    overflow: hidden !important;
    display: flex !important;
    flex-direction: column !important;
    height: 100% !important;
}
.cal-fullpage-section .weekly-cal-wrapper {
    flex: 1 !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    height: 100% !important;
    border-radius: 0 !important;
}
.cal-fullpage-section .weekly-grid-inner {
    max-height: none !important;
    min-height: 100% !important;
}

/* ===== GÜNLÜK GÖRÜNÜM TAM YÜKSEKLIK ===== */
.cal-fullpage-section #cal-view-daily.active {
    flex: 1 !important;
    overflow: hidden !important;
    display: flex !important;
    flex-direction: column !important;
    height: 100% !important;
}
.cal-fullpage-section .daily-cal-header,
#takvim.cal-fullpage-section .daily-cal-header {
    flex-shrink: 0 !important;
    border-radius: 0 !important;
    margin-bottom: 0 !important;
    border-bottom: none !important;
    background: var(--s1, #161617) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}
.cal-fullpage-section .daily-cal-wrapper,
#takvim.cal-fullpage-section .daily-cal-wrapper {
    flex: 1 !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    border-radius: 0 !important;
    border-top: none !important;
    background: var(--s1, #161617) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}
#takvim.cal-fullpage-section .daily-timeline-grid,
#takvim.cal-fullpage-section .daily-hour-label,
#takvim.cal-fullpage-section .daily-hour-cell {
    background: var(--s1, #161617) !important;
}
.cal-fullpage-section .daily-timeline-grid {
    max-height: none !important;
    min-height: 100% !important;
}

/* ===== TIKLANAMIYAN SECTION SORUNU ===== */
/* istatistikler, gunluk, sosyal gibi section'ları overflow:auto yap */
#istatistikler.page-section.active,
#gunluk.page-section.active,
#sosyal.page-section.active {
    display: block !important;
    overflow-y: auto !important;
    height: 100% !important;
}

/* ===== SECTION TIKLAMA SORUNU DÜZELTMESİ ===== */
/* Takvim dışındaki tüm active section'lar normal scroll davranışıyla */
#istatistikler.page-section.active,
#gunluk.page-section.active,
#arkadaslar.page-section.active,
#bugun.page-section.active,
#hedefler.page-section.active,
#zihin-coplugu.page-section.active,
#aliskanliklar.page-section.active,
#zamanlayici.page-section.active {
    position: relative !important;
    z-index: 1 !important;
}
/* content-area scroll reset */
.content-area {
    overflow-y: auto !important;
    position: relative !important;
}
/* Takvim kendi içinde scroll etsin, content-area'yı bypass etmesin */
#takvim.page-section.active {
    overflow: hidden !important;
    padding: 0 !important;
}

/* ===== DOCK OVERFLOW / TIKLAMA SORUNU ===== */
/* Dock'u daha kompakt yap; tüm ikonlar ekrana sığsın */
.dock {
    overflow-y: auto !important;
    scrollbar-width: thin !important;
    scrollbar-color: rgba(255,255,255,0.15) transparent !important;
    gap: 1px !important;
    padding: 8px 0 !important;
}
.dock::-webkit-scrollbar {
    display: block !important;
    width: 3px !important;
}
.dock::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.15);
    border-radius: 2px;
}
.di {
    width: 38px !important;
    height: 38px !important;
    flex-shrink: 0 !important;
    font-size: 17px !important;
}


/* ================================================================
   BUGÜN — MİNİMALİST TASARIM
   ================================================================ */

/* ── SECTION PADDING ── */
#bugun.page-section.active {
    padding: 28px 32px 0 32px;
    gap: 0;
}

/* ── HEADER: kart kutusu yok, sadece boşluk ── */
#bugun .td-header {
    background: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    padding: 0 0 20px 0 !important;
    margin-bottom: 0 !important;
    align-items: flex-start;
}

#bugun .td-header-left h2 {
    font-size: 26px !important;
    font-weight: 700 !important;
    color: var(--t1) !important;
    letter-spacing: -0.5px;
    margin-bottom: 5px;
}

#bugun .td-date {
    font-size: 13px !important;
    color: var(--t2) !important;
    letter-spacing: 0.2px;
}

#bugun .td-header-right {
    padding-top: 4px;
}

#bugun .td-progress-meta {
    margin-bottom: 6px;
}

#bugun .td-task-ratio {
    font-size: 12px !important;
    color: var(--t3) !important;
}

#bugun .td-progress-pct {
    font-size: 14px !important;
    font-weight: 700 !important;
    color: var(--a) !important;
}



#bugun .td-progress-fill {
    background: var(--a) !important;
    border-radius: 6px !important;
    transition: width 0.6s ease, background-color 0.8s ease !important;
    position: relative !important;
    overflow: hidden !important;
    animation: progress-pulse 2.4s ease-in-out infinite;
}

#bugun .td-progress-fill::after {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 60%;
    height: 100%;
    background: linear-gradient(
        90deg,
        transparent 0%,
        rgba(255,255,255,0.45) 50%,
        transparent 100%
    );
    animation: progress-shimmer 2s ease-in-out infinite;
}

#bugun .td-progress-fill.is-complete {
    animation: progress-pulse 2.4s ease-in-out infinite, progress-complete-flash 0.7s ease-out forwards;
}

#bugun .td-progress-fill.is-complete::after {
    animation: progress-shimmer 1.2s ease-in-out infinite;
}

@keyframes progress-shimmer {
    0%   { left: -60%; }
    100% { left: 110%; }
}

@keyframes progress-pulse {
    0%   { box-shadow: 0 0 0px rgba(212,144,14,0); }
    50%  { box-shadow: 0 0 7px rgba(212,144,14,0.55); }
    100% { box-shadow: 0 0 0px rgba(212,144,14,0); }
}

@keyframes progress-complete-flash {
    0%   { box-shadow: 0 0 0px rgba(74,222,128,0); }
    40%  { box-shadow: 0 0 14px rgba(74,222,128,0.85); }
    100% { box-shadow: 0 0 5px rgba(74,222,128,0.25); }
}

/* ══════════════════════════════════════════════
   GÜNÜN HEDEFİ KARTI — MİNİMAL
   ══════════════════════════════════════════════ */
#bugun .td-goal-card {
    background: rgba(212,144,14,0.07) !important;
    border: 1px solid rgba(212,144,14,0.25) !important;
    border-left: 3px solid rgba(212,144,14,0.65) !important;
    border-radius: 8px !important;
    margin: 0 0 10px 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
    transition: background 0.2s ease, border-color 0.2s ease !important;
}
#bugun .td-goal-card.is-goal-complete {
    background: rgba(74,222,128,0.06) !important;
    border-color: rgba(74,222,128,0.25) !important;
    border-left-color: rgba(74,222,128,0.60) !important;
}

/* ── Aşama 1: Setup ── */
#bugun .td-goal-setup {
    flex-direction: row !important;
    align-items: center !important;
    gap: 6px !important;
    padding: 8px 10px !important;
    flex-wrap: nowrap !important;
}
#bugun .td-goal-input {
    flex: 1 !important;
    min-width: 0 !important;
    background: transparent !important;
    border: none !important;
    outline: none !important;
    font-size: 13px !important;
    color: var(--t1) !important;
    font-family: 'Inter', sans-serif !important;
}
#bugun .td-goal-input::placeholder {
    color: rgba(212,144,14,0.40) !important;
}
#bugun .td-goal-select {
    flex-shrink: 0 !important;
    font-size: 11px !important;
    padding: 0 7px !important;
    background: transparent !important;
