    overflow: hidden !important;
    text-overflow: ellipsis !important;
    min-width: 0 !important;
    animation: goal-idle-pulse 3.5s ease-in-out infinite !important;
}
@keyframes goal-glow {
    0%   { text-shadow: none; color: #f5e0a0; }
    35%  { text-shadow: 0 0 12px rgba(212,144,14,0.90), 0 0 24px rgba(212,144,14,0.45); color: #ffe599; }
    100% { text-shadow: none; color: #f5e0a0; }
}
#bugun .td-goal-text.glowing {
    animation: goal-glow 1s ease-out forwards, goal-idle-pulse 3.5s ease-in-out infinite !important;
}
@keyframes goal-idle-pulse {
    0%   { opacity: 1; }
    50%  { opacity: 0.70; }
    100% { opacity: 1; }
}
#bugun .td-goal-btns {
