.stats-hero-row {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
    margin-bottom: 20px;
}

.hero-metric {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 28px 20px 22px;
    border-radius: 18px;
    gap: 6px;
    position: relative;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
