.pg-presence-avatar:hover { transform: scale(1.2) translateY(-2px); z-index: 2; }
/* Tooltip via data-tip */
.pg-presence-avatar[data-tip]:hover::after {
    content: attr(data-tip);
    position: absolute; bottom: calc(100% + 6px); left: 50%;
    transform: translateX(-50%);
    background: var(--s3,#262629); border: 1px solid var(--b2,rgba(255,255,255,0.12));
    color: var(--t1,#F2F2F2); padding: 4px 8px; border-radius: 6px;
    font-size: 11px; white-space: nowrap; pointer-events: none;
    box-shadow: 0 3px 10px rgba(0,0,0,0.3); z-index: 999;
}
.pg-presence-dot {
    position: absolute; bottom: -1px; right: -1px;
    width: 8px; height: 8px; border-radius: 50%;
    background: #4ade80; border: 1.5px solid var(--s1,#161617);
    animation: pg-pulse 2s ease-in-out infinite;
}
@keyframes pg-pulse {
    0%, 100% { box-shadow: 0 0 0 0 rgba(74,222,128,0.6); }
    50%       { box-shadow: 0 0 0 4px rgba(74,222,128,0); }
}
