/* ── Anket Kartı ── */
.poll-card {
    background: rgba(162,155,254,0.06);
    border: 1px solid rgba(162,155,254,0.2);
    border-radius: 12px;
    padding: 14px;
    margin-top: 6px;
    max-width: 280px;
}
.poll-question {
    font-size: 13px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 10px;
    line-height: 1.4;
}
.poll-options {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.poll-option-btn {
    position: relative;
    overflow: hidden;
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 8px;
    padding: 7px 10px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: border-color 0.15s;
    text-align: left;
}
.poll-option-btn:hover { border-color: rgba(162,155,254,0.4); }
.poll-option-btn.is-voted {
    border-color: #a29bfe;
    background: rgba(162,155,254,0.12);
}
.poll-option-bar {
    position: absolute;
    left: 0; top: 0; bottom: 0;
    background: rgba(162,155,254,0.15);
    transition: width 0.4s ease;
    z-index: 0;
    border-radius: 7px;
}
.poll-option-label {
    position: relative;
    z-index: 1;
    flex: 1;
    font-size: 12px;
    color: rgba(255,255,255,0.85);
}
.poll-option-pct {
    position: relative;
    z-index: 1;
    font-size: 11px;
    font-weight: 700;
    color: rgba(162,155,254,0.8);
    margin-left: auto;
}
.poll-footer {
    font-size: 10px;
    color: rgba(255,255,255,0.3);
    margin-top: 8px;
    padding-top: 6px;
    border-top: 1px solid rgba(255,255,255,0.06);
}

/* ── Günlük Özet Formu ── */
.ds-field { display: flex; flex-direction: column; gap: 5px; }
.ds-label {
    font-size: 12px;
    font-weight: 600;
    color: rgba(255,255,255,0.7);
    display: flex;
    align-items: center;
    gap: 6px;
}

/* ── DND / Bildirim Toggle Switch ── */
.toggle-switch {
    position: relative;
    display: inline-block;
    width: 40px;
    height: 22px;
    flex-shrink: 0;
}
.toggle-switch input { opacity: 0; width: 0; height: 0; }
.toggle-slider {
    position: absolute;
    cursor: pointer;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(255,255,255,0.15);
    border-radius: 22px;
    transition: background 0.2s;
}
.toggle-slider::before {
    content: '';
    position: absolute;
    width: 16px; height: 16px;
    left: 3px; bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
}
.toggle-switch input:checked + .toggle-slider { background: #a29bfe; }
.toggle-switch input:checked + .toggle-slider::before { transform: translateX(18px); }

