/* Modal açılma animasyonu — sayfa çevirme efekti */
/* ── Kitap Açılma: sol kapak sağa katlanarak açılıyor ── */
@keyframes bookPageTurn {
    0%   {
        opacity: 0;
        transform: perspective(1600px)
                   rotateY(-72deg)
                   rotateX(10deg)
                   scale(0.78)
                   translateZ(-160px)
                   translateY(20px);
        filter: brightness(0.5);
    }
    35%  {
        opacity: 1;
        filter: brightness(0.85);
    }
    60%  {
        transform: perspective(1600px)
                   rotateY(6deg)
                   rotateX(-1.5deg)
                   scale(1.015)
                   translateZ(12px)
                   translateY(-4px);
        filter: brightness(1.05);
    }
    80%  {
        transform: perspective(1600px)
                   rotateY(-2deg)
                   rotateX(0.5deg)
                   scale(0.997)
                   translateZ(0);
        filter: brightness(1.00);
    }
    100% {
        opacity: 1;
        transform: perspective(1600px)
                   rotateY(0deg)
                   rotateX(0deg)
                   scale(1)
                   translateZ(0)
                   translateY(0);
        filter: brightness(1);
    }
}

/* Modal — perspective ve overlay */
#book-detail-modal {
    perspective: 1600px !important;
    /* overlay background mevcut .modal-overlay kuralından geliyor, burada override etme */
}

/* Panel başlangıç durumu: opacity: 0 ama !important YOK — animation override edebilsin */
#book-detail-modal .book-detail-panel,
#book-detail-modal .notebook-layout {
    transform-style: preserve-3d !important;
    opacity: 0;
    will-change: transform, opacity, filter;
}

/* animate-open eklenince panel animasyona girer */
#book-detail-modal.animate-open .book-detail-panel,
#book-detail-modal.animate-open .notebook-layout {
    animation: bookPageTurn 0.60s cubic-bezier(0.22, 1, 0.36, 1) both !important;
}

/* ── Notebook iki sayfa arası menteşe derinliği ── */
.notebook-spine-middle {
    box-shadow:
        -4px 0 18px rgba(0,0,0,0.55),
         4px 0 18px rgba(0,0,0,0.55),
        inset -2px 0 6px rgba(0,0,0,0.30),
        inset  2px 0 6px rgba(0,0,0,0.30) !important;
    background: linear-gradient(90deg,
        #c8bfa8 0%,
        #a89880 25%,
        #b8aa90 50%,
        #a89880 75%,
        #c8bfa8 100%
    ) !important;
    position: relative !important;
}

/* Menteşe orta çizgisi */
.notebook-spine-middle::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important; bottom: 0 !important;
    left: 50% !important; transform: translateX(-50%) !important;
    width: 2px !important;
    background: linear-gradient(180deg,
        transparent,
        rgba(0,0,0,0.25) 20%,
        rgba(0,0,0,0.18) 80%,
        transparent
    ) !important;
}

