        opacity: 0;
        transform: translateY(-60px) scaleY(0.88) scaleX(0.95);
        filter: brightness(1.8) blur(1px);
    }
    55% {
        opacity: 1;
        transform: translateY(5px) scaleY(1.02) scaleX(1.0);
        filter: brightness(1.1);
    }
    75% {
        transform: translateY(-3px) scaleY(0.98);
        filter: brightness(1.0);
    }
    90% {
        transform: translateY(1px) scaleY(1.005);
    }
    100% {
        opacity: 1;
        transform: translateY(0) scaleY(1) scaleX(1);
        filter: brightness(1.0);
    }
}

