}
#bugun .td-add-sel:hover {
    background: rgba(255,255,255,.055) !important;
    border-color: rgba(255,255,255,.14) !important;
}
#bugun .td-add-sel:focus {
    border-color: rgba(212,144,14,.4) !important;
}
#bugun .td-add-sel option { background: var(--s2, #1E1E20) !important; }

/* Saat kutuları */
#bugun .td-add-time {
    display: flex !important;
    align-items: center !important;
    gap: 6px !important;
    background: rgba(255,255,255,.035) !important;
    border: 1px solid rgba(255,255,255,.08) !important;
    border-radius: 9px !important;
    padding: 7px 12px !important;
}
#bugun .time-box {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    border-radius: 0 !important;
}
#bugun .time-display {
    font-size: 12.5px !important;
    color: var(--t2) !important;
    font-variant-numeric: tabular-nums !important;
}
#bugun .td-add-time-sep {
    color: var(--t3) !important;
    font-size: 12px !important;
}

/* Submit "+" butonu */
#bugun .td-add-submit {
    width: 38px !important;
    height: 38px !important;
    min-width: 38px !important;
    border-radius: 10px !important;
    background: linear-gradient(180deg, #e3bd75, #cf9f52) !important;
    border: none !important;
    color: #1d160a !important;
    font-size: 20px !important;
    line-height: 1 !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    box-shadow: 0 6px 16px rgba(212,144,14,.2) !important;
    margin-left: auto !important;
    opacity: 1 !important;
    padding: 0 !important;
}
#bugun .td-add-submit:hover { opacity: .88 !important; }

/* Kategori ekle/sil icon butonları daha küçük */
#bugun #add-task-cat-btn,
#bugun #del-task-cat-btn {
    width: 30px !important;
    height: 30px !important;
    font-size: 12px !important;
    border-radius: 8px !important;
    background: rgba(255,255,255,.035) !important;
    border: 1px solid rgba(255,255,255,.08) !important;
    color: var(--t3) !important;
}

/* ── TİMELINE checkbox ve metin override ── */
#bugun .task-checkbox {
    width: 21px !important;
    height: 21px !important;
    min-width: 21px !important;
    border-radius: 6px !important;
    border: 1.6px solid rgba(255,255,255,.18) !important;
    background: transparent !important;
    flex-shrink: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer !important;
    transition: background .15s, border-color .15s !important;
}
#bugun .task-item.completed .task-checkbox {
    background: linear-gradient(180deg, #e3bd75, #cf9f52) !important;
    border-color: transparent !important;
}
#bugun .task-item.completed .task-checkbox::after {
    content: '✓';
    color: #1d160a;
    font-size: 12px;
    font-weight: 700;
    line-height: 1;
    display: block;
    text-align: center;
}
#bugun .task-text {
    font-size: 15.5px !important;
    font-weight: 500 !important;
    color: #f0ebe0 !important;
    letter-spacing: -.005em !important;
    line-height: 1.3 !important;
    cursor: pointer !important;
    display: block !important;
    text-align: left !important;
    width: 100% !important;
}
#bugun .task-item.completed .task-text {
    color: #6b665c !important;
    text-decoration: line-through !important;
}
/* Task meta: margin-top:7px, gap:9px */
#bugun .task-meta {
    margin-top: 7px !important;
    gap: 9px !important;
}
/* Task category tag */
#bugun .task-category-tag {
    font-size: 11.5px !important;
    color: #807b6f !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
}
/* Eski öncelik rengi checkbox override'larını geçersiz kıl */
#bugun .task-item.priority-high .task-checkbox,
#bugun .task-item.priority-medium .task-checkbox,
#bugun .task-item.priority-low .task-checkbox {
    border-color: rgba(255,255,255,.18) !important;
}
/* Task left kesinlikle soldan başlasın */
#bugun .task-left * {
    text-align: left !important;
}

/* Tamamlanan divider timeline görünümü */
#bugun .task-divider {
    padding: 6px 0 6px 82px !important;
}


