/* ── Overlay ─────────────────────────────────── */
/* ── Quick Create Modal ────────────────────── */
.pg-qc-overlay {
    position: fixed; inset: 0; z-index: 9600;
    background: rgba(0,0,0,.72); backdrop-filter: blur(14px);
    display: flex; align-items: center; justify-content: center; padding: 16px;
}
.pg-qc-overlay.hidden { display: none; }

.pg-qc-panel {
    background: #1a1a1a; border: 1px solid rgba(255,255,255,.08);
    border-radius: 20px; width: 100%; max-width: 480px;
    padding: 28px 28px 22px; box-shadow: 0 24px 80px rgba(0,0,0,.6);
    animation: pg-qc-in .22s cubic-bezier(.34,1.56,.64,1);
}
@keyframes pg-qc-in {
    from { opacity: 0; transform: scale(.94) translateY(10px); }
    to   { opacity: 1; transform: scale(1) translateY(0); }
}
.pg-qc-header {
    display: flex; align-items: center; justify-content: space-between; margin-bottom: 22px;
}
.pg-qc-header-left { display: flex; align-items: center; gap: 12px; }
.pg-qc-logo {
    width: 38px; height: 38px; border-radius: 10px;
    background: rgba(212,144,14,.15); border: 1px solid rgba(212,144,14,.25);
    display: flex; align-items: center; justify-content: center;
    color: var(--a, #D4900E); font-size: 18px; flex-shrink: 0;
}
.pg-qc-title { font-size: 16px; font-weight: 700; color: #fff; }
.pg-qc-sub   { font-size: 12px; color: #666; margin-top: 1px; }
.pg-qc-close-btn {
    width: 30px; height: 30px; border-radius: 8px; border: none;
    background: rgba(255,255,255,.05); color: #888; cursor: pointer;
    display: flex; align-items: center; justify-content: center; font-size: 14px;
    transition: all .15s;
}
.pg-qc-close-btn:hover { background: rgba(255,255,255,.1); color: #fff; }

.pg-qc-field {
    position: relative; margin-bottom: 18px;
}
.pg-qc-title-input {
    width: 100%; padding: 13px 50px 13px 16px; border-radius: 12px;
    border: 1.5px solid rgba(255,255,255,.08); background: rgba(255,255,255,.04);
    color: #fff; font-size: 15px; font-weight: 500; outline: none;
    transition: border-color .15s; box-sizing: border-box;
}
.pg-qc-title-input::placeholder { color: #444; }
.pg-qc-title-input:focus { border-color: rgba(212,144,14,.5); }
.pg-qc-title-input.error { border-color: #ef4444; animation: shake .3s; }
.pg-qc-char {
    position: absolute; right: 12px; top: 50%; transform: translateY(-50%);
