}

.pg-qc-section-label {
    font-size: 11px; font-weight: 600; color: #555; text-transform: uppercase;
    letter-spacing: .06em; margin-bottom: 8px;
}
.pg-qc-opt { text-transform: none; font-weight: 400; color: #444; letter-spacing: 0; }

.pg-qc-cat-row {
    display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 18px;
}
.pg-qc-cat-chip {
    display: flex; align-items: center; gap: 5px;
    padding: 5px 12px; border-radius: 20px; cursor: pointer;
    border: 1.5px solid rgba(255,255,255,.1); background: rgba(255,255,255,.03);
    font-size: 12px; font-weight: 600; color: #888; transition: all .14s; white-space: nowrap;
}
.pg-qc-cat-chip:hover {
    border-color: var(--cat-color, #888);
    background: color-mix(in srgb, var(--cat-color, #888) 8%, transparent);
}
.pg-qc-cat-chip.selected {
    border-color: var(--cat-color, #888); color: var(--cat-color, #fff);
