}

.pg-qc-dl-row {
    display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 8px;
}
.pg-qc-dl-btn {
    padding: 5px 12px; border-radius: 20px; font-size: 12px; cursor: pointer;
    border: 1.5px solid rgba(255,255,255,.1); background: rgba(255,255,255,.03);
