/* ── Öneri 1: Peer Cursor Overlay on Calendar ─────────────── */
.pg-pv-main-cal-cell { position: relative; overflow: visible; }
.pg-pv-peer-cursor {
    position: absolute;
    top: 2px; right: 2px;
    z-index: 10;
    pointer-events: none;
}
.pg-pv-peer-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px; height: 18px;
    border-radius: 50%;
    background: var(--peer-color, #888);
    color: #fff;
    font-size: 8px;
    font-weight: 700;
    border: 1.5px solid rgba(255,255,255,.25);
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--peer-color, #888) 30%, transparent);
    animation: pg-peer-pulse 2s ease-in-out infinite;
}
@keyframes pg-peer-pulse {
    0%, 100% { box-shadow: 0 0 0 2px color-mix(in srgb, var(--peer-color, #888) 30%, transparent); }
    50%       { box-shadow: 0 0 0 4px color-mix(in srgb, var(--peer-color, #888) 15%, transparent); }
}

/* ── Öneri 1: Typing Indicator ────────────────────────────── */
.pg-pv-typing-indicator {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 5px 8px;
    margin-bottom: 6px;
    border-radius: 8px;
    background: rgba(255,255,255,.04);
    border: 1px solid rgba(255,255,255,.07);
    font-size: 11px;
    color: var(--text-muted, #888);
}
.pg-pv-typing-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px; height: 16px;
    border-radius: 50%;
    color: #fff;
    font-size: 7px;
    font-weight: 700;
    flex-shrink: 0;
}
.pg-pv-typing-text { flex: 1; }
.pg-pv-typing-dots { display: flex; gap: 3px; align-items: center; }
.pg-pv-typing-dots span {
    width: 4px; height: 4px;
    border-radius: 50%;
    background: var(--text-muted, #888);
    animation: pg-typing-bounce .9s ease-in-out infinite;
}
.pg-pv-typing-dots span:nth-child(2) { animation-delay: .15s; }
.pg-pv-typing-dots span:nth-child(3) { animation-delay: .30s; }
@keyframes pg-typing-bounce {
    0%, 80%, 100% { transform: translateY(0); opacity: .4; }
    40%            { transform: translateY(-4px); opacity: 1; }
}

/* ── Öneri 1: Mini avatar — görevi kim ekledi ─────────────── */
.pg-pv-task-mini-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px; height: 18px;
    border-radius: 50%;
    color: #fff;
    font-size: 7px;
    font-weight: 700;
    flex-shrink: 0;
    border: 1.5px solid rgba(255,255,255,.18);
    cursor: default;
    position: relative;
}
.pg-pv-task-mini-avatar::after {
    content: attr(data-name);
    position: absolute;
    bottom: calc(100% + 6px);
    left: 50%;
    transform: translateX(-50%);
    background: rgba(20,20,35,.92);
    color: #fff;
    font-size: 10px;
    font-weight: 500;
    white-space: nowrap;
    padding: 3px 8px;
    border-radius: 6px;
    border: 1px solid rgba(255,255,255,.1);
    pointer-events: none;
    opacity: 0;
    transition: opacity .15s ease;
    z-index: 100;
}
.pg-pv-task-mini-avatar:hover::after {
    opacity: 1;
}

/* ── Öneri 2: Pending task styling ───────────────────────── */
.pg-pv-task-pending {
    opacity: .65;
    border: 1px dashed rgba(255,159,67,.4) !important;
    background: rgba(255,159,67,.04) !important;
}
.pg-pv-task-pending .pg-pv-day-task-check.disabled {
    cursor: default;
    opacity: .4;
    pointer-events: none;
}
.pg-pv-task-pending-badge {
    font-size: 10px;
    color: #ff9f43;
    display: flex;
    align-items: center;
    gap: 3px;
    white-space: nowrap;
}
.pg-pv-task-act-btn.approve {
    color: #06d6a0;
    border-color: rgba(6,214,160,.3);
}
.pg-pv-task-act-btn.approve:hover {
    background: rgba(6,214,160,.12);
}

/* ── Öneri 2: Collab toggle switch ───────────────────────── */
.pg-collab-toggle-label {
    display: flex;
    align-items: center;
    cursor: pointer;
    flex-shrink: 0;
}
.pg-collab-toggle-label input { display: none; }
.pg-collab-toggle-track {
    display: block;
    width: 34px; height: 18px;
    border-radius: 9px;
    background: rgba(255,255,255,.12);
    border: 1px solid rgba(255,255,255,.15);
    position: relative;
    transition: background .2s;
}
.pg-collab-toggle-track::after {
    content: '';
    position: absolute;
    top: 2px; left: 2px;
    width: 12px; height: 12px;
    border-radius: 50%;
    background: #fff;
    transition: transform .2s;
}
.pg-collab-toggle-label input:checked + .pg-collab-toggle-track {
    background: #06d6a0;
    border-color: #06d6a0;
}
.pg-collab-toggle-label input:checked + .pg-collab-toggle-track::after {
    transform: translateX(16px);
}

/* ── Öneri 3: Ghost Toast ─────────────────────────────────── */
#pg-ghost-toast-container {
    position: fixed;
    top: 64px;
    right: 16px;
    z-index: 99999;
    display: flex;
    flex-direction: column;
    gap: 8px;
    pointer-events: none;
}
.pg-ghost-toast {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    border-radius: 12px;
    background: rgba(20,20,35,.88);
    backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,.1);
    box-shadow: 0 4px 20px rgba(0,0,0,.45);
    font-size: 12px;
    color: rgba(255,255,255,.85);
    max-width: 260px;
    opacity: 0;
    transform: translateX(12px);
    transition: opacity .22s ease, transform .22s ease;
    pointer-events: none;
}
.pg-ghost-toast.visible {
    opacity: 1;
    transform: translateX(0);
}
.pg-ghost-toast.hiding {
    opacity: 0;
    transform: translateX(8px);
}
.pg-ghost-toast-avatar {
    width: 22px; height: 22px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 8px;
    font-weight: 700;
    color: #fff;
    flex-shrink: 0;
}
.pg-ghost-toast-body {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-wrap: wrap;
    gap: 3px;
    align-items: baseline;
    line-height: 1.4;
}
.pg-ghost-toast-name { font-weight: 700; }
.pg-ghost-toast-action { color: rgba(255,255,255,.55); font-size: 11px; }
.pg-ghost-toast-target { color: rgba(255,255,255,.75); font-style: italic; font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 150px; }
.pg-ghost-toast-icon { font-size: 13px; flex-shrink: 0; }

/* ── Öneri 3: Notification badge on header ────────────────── */
.pg-pv-notif-btn { position: relative; }
.pg-pv-notif-badge {
