}
.cp-sched-help-popover > button:hover { color: #fff; background: var(--s2); }
.cp-sched-help-popover .cp-popover-panel { left: 0; min-width: 220px; }
.cp-sched-help-popover .cp-popover-panel::before {
    content: ''; position: absolute; bottom: 100%; left: 12px;
    border: 7px solid transparent; border-bottom-color: var(--s2);
}
.cp-sched-help-panel p { margin: 0; font-size: 11.5px; line-height: 1.5; color: var(--text-muted); }
.cp-perf-name-link { cursor: pointer; text-decoration: none; }
.cp-perf-name-link:hover { text-decoration: underline; text-decoration-color: rgba(96,165,250,0.5); }
.cp-perf-dist {
    margin: 14px 0 16px; padding: 12px 14px; border: 1px solid rgba(96,165,250,0.22); border-radius: var(--r, 14px);
    background: var(--s2);
    transition: transform 0.15s, border-color 0.15s;
