.cp-perf-dist-title small { font-weight: 500; color: var(--text-muted); margin-left: 4px; }
.cp-perf-dist-svg { width: 100%; height: auto; display: block; }
.cp-perf-dist-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; margin-top: 8px; font-size: 11px; color: var(--text-muted); }
.cp-perf-dist-swatch { display: inline-block; width: 9px; height: 9px; border-radius: 2px; margin-right: 4px; vertical-align: middle; }
.cp-perf-dist-skew-note { opacity: 0.8; }
.cp-perf-dist-hint { flex-basis: 100%; opacity: 0.75; }

/* ── Kendi Aynan (öğrenci) — pozitif çerçeve: kimseyle kıyaslamaz, sadece kendi serisini gösterir ── */
.cp-streak-card {
    display: flex; align-items: center; gap: 14px; padding: 14px 16px; margin-bottom: 14px;
    border-radius: var(--r, 14px); background: var(--bl10); border: 1px solid rgba(96,165,250,0.3);
    transition: transform 0.15s, border-color 0.15s;
    opacity: 0; animation: dhsCardIn 0.4s ease forwards;
}
.cp-streak-card:hover { transform: translateY(-2px); border-color: rgba(96,165,250,0.5); }
.cp-streak-card--hot { background: var(--a10); border-color: rgba(212,144,14,0.3); }
.cp-streak-num { font-size: 26px; font-weight: 800; flex-shrink: 0; min-width: 44px; text-align: center; }
.cp-streak-body { min-width: 0; }
.cp-streak-title { margin: 0 0 3px; font-weight: 700; color: #fff; font-size: 13.5px; }
.cp-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 700; }

.cp-trend.up { color: #2ed573; }
.cp-trend.down { color: #ff6b6b; }
.cp-hint { font-size: 11.5px; color: var(--text-muted); margin: 10px 0 0; line-height: 1.6; }
.cp-asg-form { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.cp-asg-list { display: flex; flex-direction: column; gap: 10px; }

/* ── Ödev kartı — Bugün sekmesindeki .tl-card-inner ile aynı düz/minimalist
   dil: sabit renk yok, ince kenarlık, hover'da sadece kenarlık/arkaplan
   hafifçe aydınlanır (yükselme/gölge/ikon rozeti yok). Durum, sadece ince
   bir sol kenarlıkla (border-left) belirtilir. */
.cp-asg {
    display: flex; align-items: flex-start; justify-content: space-between; gap: 14px;
    padding: 14px 16px; border-radius: 13px;
    background: rgba(255,255,255,.022); border: 1px solid rgba(255,255,255,.06);
    border-left: 2px solid rgba(116,185,255,0.4);
    transition: border-color .15s, background .15s;
}
