.cp-asg[data-accent="important"] { border-left-color: rgba(254,202,87,0.5); }
.cp-asg[data-accent="done"] { border-left-color: rgba(46,213,115,0.5); }
.cp-asg[data-accent="closed"] { border-left-color: rgba(255,255,255,0.15); }
.cp-asg:hover { border-color: rgba(217,177,106,.28); background: rgba(255,255,255,.035); }
.cp-asg--closed { opacity: 0.6; }


.cp-asg-main { display: flex; flex-direction: column; gap: 4px; min-width: 0; flex: 1; }
.cp-asg-title { color: var(--t1, #fff); font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.cp-asg-targeted-badge {
    font-size: 9.5px; font-weight: 700; color: #a29bfe; padding: 1px 7px; border-radius: 20px;
    background: rgba(162,155,254,0.1); border: 1px solid rgba(162,155,254,0.25); white-space: nowrap;
}
.cp-asg-desc { color: var(--text-muted); font-size: 11px; line-height: 1.4; }
.cp-asg-meta { color: var(--text-muted); font-size: 10.5px; display: flex; align-items: center; flex-wrap: wrap; gap: 4px; }
.cp-asg-actions { display: flex; gap: 4px; flex-shrink: 0; }
/* Öğrenci: durum rozeti kartın en sağında, üstte — altında (varsa) "Geri Al" butonu. */
.cp-asg-actions--student { flex-direction: column; align-items: flex-end; gap: 6px; }
.cp-asg-btn { font-size: 11px; padding: 5px 9px; }
.cp-asg-btn--danger { color: #ff6b6b; }

.cp-asg-priority {
    font-size: 9.5px; font-weight: 700; padding: 1px 8px 1px 7px; border-radius: 20px; white-space: nowrap;
    display: inline-flex; align-items: center; gap: 3px;
}
.cp-asg-priority--important { color: #feca57; background: rgba(254,202,87,0.1); border: 1px solid rgba(254,202,87,0.28); }
.cp-asg-priority--urgent { color: #ff6b6b; background: rgba(255,107,107,0.1); border: 1px solid rgba(255,107,107,0.3); }

.cp-asg-attach {
    display: inline-flex; align-items: center; gap: 5px; font-size: 10.5px; font-weight: 600; color: #74b9ff;
    text-decoration: none; width: fit-content; padding: 3px 8px 3px 7px; border-radius: 20px;
    background: rgba(116,185,255,0.08); border: 1px solid rgba(116,185,255,0.2); transition: background 0.15s;
}
.cp-asg-attach:hover { background: rgba(116,185,255,0.14); text-decoration: none; }

.cp-asg-grade {
    display: inline-flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 600; color: #2ed573;
    padding: 3px 9px; border-radius: 20px; background: rgba(46,213,115,0.08); border: 1px solid rgba(46,213,115,0.22);
    width: fit-content;
}
.cp-grade-list { display: flex; flex-direction: column; gap: 5px; margin-top: 7px; }
.cp-grade-row { display: flex; align-items: center; gap: 5px; }
.cp-grade-row-name { flex: 1; font-size: 11px; color: var(--text-muted); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cp-grade-input { width: 52px; flex-shrink: 0; padding: 4px 7px; font-size: 11px; }
.cp-grade-feedback { flex: 2; min-width: 90px; padding: 4px 7px; font-size: 11px; }
.cp-grade-save { flex-shrink: 0; padding: 4px 8px; font-size: 10.5px; }
/* ── Ödev oluşturma formu — Sınıf Paneli'nin geri kalanıyla (Şubeler, Ders
   Programı vb.) aynı teal vurgu rengini kullanır (2026-07-11, kullanıcı
   geri bildirimi: eskiden Bugün sekmesiyle aynı amber tondaydı, panelin
   geneliyle uyumsuz duruyordu — bkz. #4ecdc4 cp-roster-pillbtn--accent). ── */
.cp-asg-create {
    display: flex; flex-direction: column; gap: 8px; margin-bottom: 12px;
    background: rgba(78,205,196,0.04); border: 1px solid rgba(78,205,196,0.18);
    border-radius: 8px; padding: 10px 12px;
}
.cp-asg-create-row { display: flex; gap: 8px; align-items: center; }
.cp-asg-create-row--main { gap: 8px; }
.cp-asg-title-input {
    flex: 1; min-width: 0; font-size: 13px; color: var(--t1, #fff); font-family: 'Inter', sans-serif;
    background: transparent; border: 1px solid transparent; outline: none; padding: 7px 0;
}
.cp-asg-title-input::placeholder { color: var(--t3, var(--text-muted)); }
.cp-asg-submit-btn {
    flex-shrink: 0; width: 32px; height: 32px; min-width: 32px; border-radius: 7px;
    background: rgba(78,205,196,0.16); border: none; color: #4ecdc4;
    font-size: 13px; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center;
    transition: background 0.15s, opacity 0.15s;
}
.cp-asg-submit-btn:hover { background: rgba(78,205,196,0.28); opacity: 1; }
.cp-asg-char-hint { font-size: 10px; color: var(--text-muted); text-align: right; margin: -4px 2px 4px 0; opacity: 0.75; }
.cp-asg-pill-input, .cp-asg-desc-input {
    background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.1);
    color: var(--t1, #fff); font-family: 'Inter', sans-serif; font-size: 11px;
    padding: 4px 8px; border-radius: 6px; cursor: pointer; outline: none;
    transition: border-color .15s, background .15s;
}
.cp-asg-pill-input:hover { background: rgba(255,255,255,.06); }
.cp-asg-pill-input:focus { border-color: rgba(78,205,196,.4); }
.cp-asg-pill-input option { background: var(--s2, #1E1E20); }
.cp-asg-desc-input {
    width: 100%; box-sizing: border-box; resize: vertical; min-height: 34px; cursor: text; color: var(--t1, #fff);
    font-size: 13px; padding: 7px 12px; border-radius: 7px;
}
.cp-asg-desc-input::placeholder { color: var(--text-muted); }
.cp-asg-create-opts { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.cp-asg-create-opts .cp-asg-pill-input { flex: 0 1 auto; min-width: 120px; }
.cp-asg-create-opts input[type="date"].cp-asg-pill-input { min-width: 110px; }
.cp-asg-pill-icon-btn {
    flex-shrink: 0; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center;
    border-radius: 6px; background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.1);
    color: var(--text-muted); cursor: pointer; font-size: 11px; transition: background 0.15s, color 0.15s;
}
.cp-asg-pill-icon-btn:hover { color: #4ecdc4; background: rgba(255,255,255,.06); }
.cp-asg-file-label { display: flex; align-items: center; cursor: pointer; }
.cp-asg-file-label span {
    display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--text-muted);
    padding: 4px 8px; border-radius: 6px; background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.1);
    white-space: nowrap; transition: border-color .15s, background .15s;
}
.cp-asg-file-label:hover span { color: #4ecdc4; background: rgba(255,255,255,.06); }





.cp-asg-step-edit-row.is-dragging { opacity: 0.4; }






.cp-asg-steps-checklist {
    margin-top: 6px; padding: 8px 10px; border-radius: 9px;
    background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06);
    display: flex; flex-direction: column; gap: 8px;
}
.cp-asg-step-row { display: flex; align-items: flex-start; gap: 8px; font-size: 12.5px; color: var(--text-muted); cursor: pointer; }
.cp-asg-step-row input { width: 15px; height: 15px; accent-color: #a29bfe; cursor: pointer; margin-top: 2px; flex-shrink: 0; }
.cp-asg-step-row-body { display: flex; flex-direction: column; gap: 2px; }
.cp-asg-step-row-title { color: #fff; }
.cp-asg-step-row--rich .cp-asg-step-row-title { font-weight: 600; }
.cp-asg-step-row-desc { font-size: 11.5px; color: var(--text-muted); }
.cp-asg-step-row-link { font-size: 11.5px; color: #a29bfe; text-decoration: none; }
.cp-asg-step-row-link:hover { text-decoration: underline; }
.cp-asg-step-breakdown {
    display: flex; flex-direction: column; gap: 6px;
