.cp-asg-step-bd-title { flex: 0 0 40%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cp-asg-step-bd-bar { flex: 1; height: 5px; border-radius: 4px; background: rgba(255,255,255,0.06); overflow: hidden; }
.cp-asg-step-bd-fill { height: 100%; background: #a29bfe; border-radius: 4px; }
.cp-asg-step-bd-count { flex: 0 0 auto; font-weight: 600; color: #fff; min-width: 32px; text-align: right; }
.cp-sub-student-detail summary { cursor: pointer; list-style: none; }
