.cp-asg-submit-form {
    margin-top: 6px; padding: 8px 10px; border-radius: 9px;
    background: rgba(255,255,255,0.02); border: 1px solid rgba(255,255,255,0.06);
}
.cp-asg-submit-form summary {
    cursor: pointer; font-size: 11px; font-weight: 700; color: #74b9ff;
    list-style: none; user-select: none; display: flex; align-items: center; gap: 5px;
}
