.cp-asg-submit-form[open] summary::before { content: '▾'; }
.cp-asg-submit-body { display: flex; flex-direction: column; gap: 6px; margin-top: 7px; }
.cp-asg-submit-note { width: 100%; box-sizing: border-box; resize: vertical; font-size: 11px; }
/* Dosya ekle + Teslim Et aynı satırda — buton artık genel büyük CTA (.control-btn)
   yerine dosya etiketiyle aynı ölçekte, küçük bir pill. */
.cp-asg-submit-row { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; }
.cp-asg-submit-confirm {
    display: flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 700;
    color: #1d160a; background: linear-gradient(180deg, #e3bd75, #cf9f52);
    border: none; padding: 4px 10px; border-radius: 6px; cursor: pointer;
    white-space: nowrap; transition: opacity .15s;
}
